  'sarasvati', 'Sarasvati', NULL, 'Water Goddess', 'rifts', 'Deity', '10th level water warlock, 6th level ley line walker', 10, 'Unprincipled', NULL, '6 ft, 7 in (2.0 m)', '150 lbs (67.5 kg)', '{"IQ":26,"ME":21,"MA":24,"PS":23,"PP":17,"PE":22,"PB":26,"Spd":38}', 1000, 1300, 23000, 2500, 1000, NULL, 12, '{"attacks":4,"strike":3,"parry":4,"dodge":4,"pull":2,"roll":4,"damage":8}', '+5 save vs horror factor, +5 save vs magic, +4 save vs psionics; 4,600 M.D.C. on Rifts Earth; 2 attacks/melee by magic or psionics; Gift of Inspiration (1x/day): sudden insight or +20% to a relevant skill for an artist/scientist', NULL, 'Hand to Hand: Basic; all technical, science and domestic skills, speaks/reads all languages, all at 90%', 'Nightvision 200 ft, sees invisible, bio-regenerates 4D6x10 M.D.C./minute, turns 1D6x100 dead, teleports self 88%/dimensionally 65%, healing touch restores 4D6', 'All elemental water spells at 10th level; Normal spells levels 1-4; Minor curse (6th level)', 'All sensitive, physical and healing powers; Hydrokinesis; Mind block auto-defense; Mind bolt', NULL, NULL, 'None - relies on magic and her powers', NULL, 'Contradictory - generous and charming in public, but arrogant, petty and childish in private; devoted patron of artists', NULL, NULL, 'Water goddess and patron of arts and sciences; formerly wed to both Vishnu and Brahma; spoiled and demanding even for a goddess', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.121');
  'brahma', 'Brahma', NULL, 'The Wise', 'rifts', 'Deity', '20th level ley line walker, temporal wizard, and 12th level diabolist and mind melter', 20, 'Principled', NULL, '9 ft (2.7 m)', '800 lbs (360 kg)', '{"IQ":30,"ME":35,"MA":27,"PS":40,"PP":24,"PE":32,"PB":18,"Spd":590}', 3000, 9000, 120000, 20000, 2000, NULL, 19, '{"attacks":7,"strike":7,"parry":9,"dodge":9,"roll":2,"damage":25}', '+10 save vs magic, +10 save vs psionics (no horror-factor save bonus printed); Spd 590 is flight only (400 mph/640 km, hovers/flies); M.D.C. halved to 60,000/12,000 for 1D4 weeks after visiting the Unnameable Beings'' prison (roughly every 6-8 weeks), S.D.C./hit points also halved then; 24,000 M.D.C. on Rifts Earth; 4 attacks/melee by magic or psionics; can summon 1D4 each of seraphs/tharsis/ariels/cherubs, or up to 50,000 spirits of light in a dire emergency; commands the other pantheon gods and their minions', NULL, 'Hand to Hand: Expert; all technical, science, espionage, wilderness skills plus navigation, all at 98%; magically knows all languages; W.P. Sword, W.P. Blunt', 'Nightvision 1000 ft, sees all light/radiation spectrums and invisible beings, turns invisible, immune to heat/cold, resists fire/energy (half dmg), impervious to poison/disease, turns 1D6x1000 dead, teleports 98%/dimensionally 96%, senses rifts/ley lines planet-wide; Vision of Truth instantly reveals a being''s alignment and nature', 'All spells levels 1-15 at 20th level; All temporal magic spells at 15th level', 'All sensitive, healing and physical powers; Mind block auto-defense; Mind bolt; P.P.E. shield; Telekinesis; Pyrokinesis; Psi-sword; Psi-shield; Telekinetic force field', NULL, NULL, 'Scepter of Brahma (greatest rune weapon, I.Q. 13, telepathic link; 3D4x10 M.D., doubled vs vampires/alien intelligences; casts water and general spells 3x/24hrs at 10th level); Heavenly Bow (indestructible black rune bow; Energy Arrows 2D6x10 M.D.; Curse Arrows cast curse spells; Anti-Undead Arrows destroy vampires, max 24/day); Beads of Power (12 strung beads: Energy x3 300 P.P.E. each, Destruction x3 1D6x10 M.D./20ft radius, Protection x3 grant armor of Ithan 200 M.D.C., Negation x3 cast anti-magic cloud); Sacred Book of Knowledge (lets Brahma cast any spell, including elemental, temporal and necromantic, by reading a passage)', NULL, 'Imperious and distant, ignoring trivial matters; four heads speak in unnerving unison; fights until foes are utterly incapacitated', 'Ahura Mazda; Ra; Marduk; Zurvan', 'Vampire intelligences; the Splugorth; the Asuras', 'Supreme wise overlord god of the Indian pantheon, secretly spending his power to keep the Unnameable Beings imprisoned', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.122-123');
  'vishnu', 'Vishnu', NULL, 'The Preserver', 'rifts', 'Deity', '20th level ley line walker and warrior, 10th level fire warlock and mind melter', 20, 'Principled', NULL, '7 ft tall (2.1 m)', '280 lbs (126 kg)', '{"IQ":26,"ME":22,"MA":24,"PS":55,"PP":26,"PE":28,"PB":25,"Spd":88}', 3000, 5500, 75000, 9000, 2000, NULL, 18, '{"attacks":12,"initiative":6,"strike":8,"parry":11,"dodge":11,"pull":6,"roll":3}', '+10 save vs horror factor, +9 save vs magic, +6 save vs psionics; 15,000 M.D.C. on Rifts Earth; Horror Factor 18 = awe to good, fear to evil; 3 attacks/melee by magic; Light of Deliverance (500 P.P.E., 1 melee round to activate): evil supernaturals within 1000 ft at -2 strike/parry/dodge and -25% HP/M.D.C., regeneration and teleport disrupted, for 4 rounds (extendable for another 500 P.P.E.); good allies get +2 strike/parry/dodge, +6 save horror factor, +2 save magic/psionics; can project up to 22 Avatars of himself (e.g. Krishna)', NULL, 'Hand to Hand: Martial Arts; all science, domestic, wilderness skills plus art, demon lore, detect ambush, wilderness survival, tracking, all at 98%; magically understands all languages', 'Nightvision 1200 ft, sees invisible, bio-regenerates 1D6x100 M.D.C./minute, turns 1D6x100 dead, teleports self 88%/dimensionally 75%, healing touch restores 4D6', 'All magical spells levels 1-15 at 20th level; All elemental fire spells at 10th level', 'All physical and sensitive powers; Psi-sword; Mind bolt; Mind block auto-defense; Telekinesis; Telekinetic force field', NULL, NULL, 'Sudarsana the Discus (greatest rune weapon, I.Q. 16, telepathic link; burns evil touchers 1D4x10 M.D.; 2D6x10 M.D., doubled vs evil; returns when thrown; disrupts a target''s teleport attempt); Panchajanya the Shell (+2 to dodge; can raise a 500 M.D.C. energy bubble shield over a 20 ft/6 m radius); Kaunodaki the Mace (greatest rune weapon, I.Q. 11; burns evil touchers 1D6x10 M.D.; 4D4x10 M.D., tripled vs dragons/vampire intelligences; casts transferal, banishment, mystic portal, time hole 3x/24hrs at 12th level); Sarnga the Magic Bow (4000 ft/1200 m range, 2D6x10 M.D. energy arrows)', NULL, 'Gentle and courteous with mortals but a whirlwind of destruction in combat; devoted to Light and resentful of Indra''s past vanity', 'Brahma; Garuda; Hanuman; Ahura Mazda; Mithras; Isis; Ra; Marduk', 'Demons everywhere; the Splugorth (especially the Kittani and the Overlords)', 'One of the Divine Triad, a blue-skinned four-armed god who sends Avatars like Krishna across the Megaverse to fight evil', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.123-124');
  'krishna', 'Krishna', NULL, 'The Avatar', 'rifts', 'Avatar', '10th level ley line walker and warrior, 5th level fire warlock and mind melter', 10, 'Anarchist', NULL, '6 ft tall (1.8 m)', '195 lbs (87.7 kg)', '{"IQ":26,"ME":22,"MA":24,"PS":55,"PP":26,"PE":28,"PB":25,"Spd":88}', 600, 800, 14000, 1000, 200, NULL, 15, '{"attacks":6,"initiative":5,"strike":8,"parry":11,"dodge":11,"pull":3,"roll":3}', '+7 save vs horror factor, +7 save vs magic, +5 save vs psionics; an Avatar''s M.D.C. formula is 3D6x1000 (rolled 14,000 here), 2,800 M.D.C. on Rifts Earth; 2 attacks/melee by magic', '[{"name":"Dance","pct":92},{"name":"Singing","pct":98},{"name":"Fishing","pct":98},{"name":"Detect ambush","pct":98},{"name":"Tracking","pct":92},{"name":"Wilderness survival","pct":98},{"name":"Language: Dragonese/Elf","pct":98},{"name":"Language: Atlantean","pct":98}]', 'Hand to Hand: Martial Arts; wrestling, boxing, W.P. Sword, W.P. Blunt; plus 5 Indian languages and dialects, all at 98%', 'Nightvision 200 ft, sees/turns invisible, resists energy attacks (half dmg), bio-regenerates 2D6x10 M.D.C./minute, turns 1D6x100 dead, teleports self 88%/dimensionally 65%, healing touch restores 4D6', 'All spells levels 1-8; Protection circle; Banishment; Mystic portal; Anti-magic cloud; Calm storms; Summon and control storms; Dimensional portal; All elemental fire spells levels 1-5', 'All sensitive and physical powers; Mind block auto-defense', NULL, NULL, 'Vishnu''s enchanted mace Kaunodaki (borrowed; see Vishnu)', NULL, 'Playful, arrogant and supremely overconfident; brave, lecherous and headstrong, used to always winning', 'Occasionally adventures with heroes and champions; protected by Vishnu', 'Demons; the undead; several offended gods; husbands and fathers he has wronged', 'Vishnu''s most popular Avatar, born through a mortal woman but wielding god-like power; adventurous and famously lecherous', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.124-125');
  'siva', 'Siva', NULL, 'The Destroyer', 'rifts', 'Deity', '20th level warrior, 18th level mystic and mind melter', 20, 'Aberrant with selfish tendencies', NULL, '12 ft (3.6 m)', '400 lbs (180 kg)', '{"IQ":23,"ME":23,"MA":21,"PS":60,"PP":24,"PE":27,"PB":20,"Spd":88}', 2000, 5000, 70000, 6000, 2000, NULL, 18, '{"attacks":12,"initiative":5,"strike":10,"parry":10,"dodge":10,"pull":4,"roll":6}', '+10 save vs horror factor, +7 save vs magic, +5 save vs psionics; 14,000 M.D.C. on Rifts Earth; 8 attacks/melee by psionics or 3 by magic; surrounds self with force fields/protective spells adding a few hundred M.D.C.; Siva''s Third Eye: 2D6x100 M.D. beam usable once every 4 melee rounds (counts as all his attacks that round), costs 500 P.P.E.', NULL, 'Hand to Hand: Assassin; all wilderness, domestic, technical skills plus concealment, palming, horsemanship, Dragonese/Elven, 12 Indian languages/dialects, all at 98%; Athletics, wrestling, boxing, W.P. Sword, W.P. Archery and targeting', 'Nightvision 2000 ft, sees/turns invisible, resists fire/energy (half dmg), impervious to cold, bio-regenerates 1D6x100 M.D.C./minute, turns 1D6x100 dead, teleports self 93%/dimensionally 82%, healing touch restores 4D6', 'All spells levels 1-15 at 18th level', 'ALL psionic powers, equal to an 18th level mind melter', NULL, NULL, 'Pinaka, Siva''s Trident (rune weapon, I.Q. 10, telepathic link; burns aberrant-evil-alignment touchers 1D4x10 M.D.; 2D4x10 M.D., tripled vs alien intelligences, doubled vs demons/vampires; casts water and air spells 3x/24hrs at 10th level); Ajagawa, Siva''s Bow (4000 ft/1200 m range, 1D6x10 M.D. arrows, needs P.S. 30 to draw, +2 to strike); Khatwanga the Mace (3D6x10 M.D.); Siva''s Sword (an Impaler, described in Rifts Atlantis); Siva''s Cobras (three magic snakes, 300 M.D.C. each, 30 ft long, bite 3D6 M.D. plus a weakening poison, can entangle)', NULL, 'Informal and charming with a prankish streak, but quick-tempered, violent and coldly cruel to enemies', 'The Divine Triad; Parvati (wife); other gods of war and light; some indebted demon lords', 'Standard demons; Indra; Splugorth High Lords and Conservators', 'One of the Divine Triad, a three-eyed storm god and destroyer of demons who also keeps demons as servants', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.125-127');
  'parvati', 'Parvati', NULL, NULL, 'rifts', 'Deity', '18th level warrior and ley line walker', 18, 'Unprincipled', NULL, '10 ft (3 m)', '400 lbs (180 kg)', '{"IQ":23,"ME":27,"MA":25,"PS":40,"PP":24,"PE":26,"PB":23,"Spd":66}', 1500, 2500, 40000, 6000, 500, NULL, 17, '{"attacks":10,"initiative":4,"strike":7,"parry":10,"dodge":10,"pull":3,"roll":3,"damage":25}', '+10 save vs horror factor, +7 save vs magic, +7 save vs psionics; 8,000 M.D.C. on Rifts Earth; 2 attacks/melee by magic; also known as Uma, Durga and Devi (Kali, once an aspect of her, became a separate being)', NULL, 'Hand to Hand: Martial Arts; all domestic and technical skills plus wilderness survival, tracking, prowl, detect ambush, all at 98%; magically speaks all languages; W.P. Sword, W.P. Blunt, W.P. Archery and targeting', 'Nightvision 1200 ft, hawk-like vision, exceptional hearing, sees/turns invisible, bio-regenerates 4D6x10 M.D.C./minute, turns 1D6x100 dead, teleports self 88%/dimensionally 65%, healing touch restores 4D6', 'All spells levels 1-8; Curse: phobia; Protection circle: simple; Banishment; Control/enslave entity; Remove curse; Calm storms; Close rift; Summon lesser being; Sanctum; Dimensional portal', 'All sensitive powers; Mind bolt; Psi-shield; Psi-sword', NULL, NULL, 'Sashonu, Parvati''s magic sword (3D4x10 M.D., doubled vs demons; casts magic net, wisps of confusion, energy field 3x/day at 8th level; can create ten 1D4x10 M.D. spectral replicas of itself, one per arm)', NULL, 'Complex and shifting personality - sweet damsel, boisterous warrior-woman, or bloodthirsty berserker by turns', NULL, NULL, 'Siva''s powerful warrior wife, also called Uma, Durga and Devi; a demon-slayer secretly falling for Agni', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.127-128');
  'skanda', 'Skanda', NULL, 'God of War', 'rifts', 'Deity', '20th level knight/warrior', 20, 'Scrupulous', NULL, '10 ft tall (3 m)', '400 lbs (180 kg)', '{"IQ":19,"ME":30,"MA":18,"PS":60,"PP":27,"PE":29,"PB":18,"Spd":88}', 1000, 1500, 25000, 400, NULL, NULL, 16, '{"attacks":12,"initiative":6,"strike":8,"parry":11,"dodge":11,"pull":6,"roll":3}', '+10 save vs horror factor, +8 save vs magic, +9 save vs psionics; 5,000 M.D.C. on Rifts Earth; also known as Karttikeya; has no magical or psionic knowledge', NULL, 'Hand to Hand: Martial Arts; all espionage, military, wilderness and weapon proficiency skills; operates a computer, pilots hover vehicles/tanks, horsemanship, all at 80%; speaks/reads Dragonese/Elven, 5 Indian languages, all at 98%', 'Nightvision 600 ft, sees/turns invisible, hawk-like vision, resists energy attacks (half dmg), bio-regenerates 3D6x10 M.D.C./minute, teleports self 68%/dimensionally 44%', NULL, NULL, NULL, NULL, 'Enchanted Scale Mail Armor (2,000 M.D.C., featherlight and silent); Sword of Atlantis (described in Rifts Atlantis); Giant Plasma Sword (adds 1D4x10 M.D. to P.S. damage); Plasma Cannon (1D4x10 M.D., range 3000 ft/915 m, payload 30 shots, regenerates 5/hour); Techno-Wizard War Helmet (impervious to possession/mind control, sees invisible/infrared/ultraviolet, radar HUD tracks up to 72 targets at 20 miles/32 km, +1 to strike)', NULL, 'Quiet, dedicated warrior with no patience for talk, arguments or delays; picks the best course of action and follows it', NULL, NULL, 'Son of Siva and Parvati and fanatical god of war; disappeared after clashing with Splugorth forces, feared enslaved by them', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.128-129');
  'ganesa', 'Ganesa', NULL, 'The Elephant God', 'rifts', 'Deity', '20th level scholar/sage, 15th level ley line walker, diabolist and shifter', 20, 'Scrupulous', NULL, '7 ft (2.1 m) tall', '600 lbs (270 kg)', '{"IQ":28,"ME":24,"MA":25,"PS":40,"PP":12,"PE":25,"PB":10,"Spd":16}', 800, 1300, 21000, 2000, 240, NULL, 12, '{"attacks":6,"initiative":1,"strike":3,"parry":6,"dodge":6,"pull":4,"roll":4,"damage":25}', '+6 save vs horror factor, +6 save vs magic, +6 save vs psionics; 4,200 M.D.C. on Rifts Earth; flies/hovers at Spd 22 (15 mph/24 km); very short for a god (7 ft); 2 attacks/melee by magic', NULL, 'Hand to Hand: Basic; all science, technical, communication, mechanical, electrical and piloting skills plus wilderness survival, all at 90%; magically knows all languages; W.P. Sword, W.P. Blunt', 'Nightvision 200 ft, sees invisible, bio-regenerates 1D6x10 M.D.C./minute, turns 1D6x100 dead, teleports self 68%/dimensionally 46%, healing touch restores 4D6, fully prehensile trunk, keen sense of smell', 'All magic spells levels 1-6; Circle of flame; Invisibility: superior; Wind rush; Mute; Hallucination; Banishment', 'All sensitive powers', NULL, NULL, 'Ganesa''s Club (greater rune weapon, gift from Siva; 2D4x10 M.D., returns when thrown; casts invulnerability, globe of silence, invisibility: superior, negate magic, stone to flesh 3x/day at 10th level); Ganesa''s Discus (1D6x10 M.D., range 2000 ft/610 m); The Riding Rat (magical mount the size of an elephant, 500 M.D.C., Spd 88, bite 4D6 M.D., +2 to strike, +3 to dodge)', NULL, 'Congenial, humorous scholar-diplomat who prefers parley to combat; gentle and beloved adviser to the pantheon', NULL, NULL, 'Elephant-headed god of wisdom and remover of obstacles, Brahma''s most knowledgeable adviser and Skanda''s brother', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.129-130');
  'hanuman', 'Hanuman', NULL, 'The Monkey King', 'rifts', 'Deity', '16th level warrior, ley line walker and diabolist', 16, 'Scrupulous', NULL, 'Thumb-sized up to 30 ft (9 m) tall in giant form', 'Varies, up to 50 tons', '{"IQ":25,"ME":24,"MA":26,"PS":60,"PP":27,"PE":26,"PB":16,"Spd":88}', 800, 1200, 20000, 2000, NULL, NULL, 12, '{"attacks":7,"initiative":4,"strike":8,"parry":14,"dodge":14,"pull":8,"roll":8}', '+35 to S.D.C. damage; +7 save vs magic; +6 save vs psionics; giant form (20ft+): M.D.C. 60,000 (4,000 human form / 12,000 giant form on Rifts Earth), Horror Factor 17, dodge reduced to +4, roll reduced to +2, Spd 220 flying (150mph/241km); Hanuman''s Roar (giant form only) heard 2D4 miles', '[{"name":"Detect Ambush","pct":90},{"name":"Concealment","pct":90},{"name":"Palming","pct":90},{"name":"Pick Pockets","pct":90},{"name":"Streetwise","pct":90},{"name":"Art","pct":90},{"name":"Navigation","pct":90},{"name":"Language: Dragonese/Elven","pct":98},{"name":"Language: Atlantean","pct":98},{"name":"Language: Greek","pct":98},{"name":"Language: Sanskrit","pct":98}]', 'All wilderness and domestic skills; 4 unnamed Indian languages at 98%; Wrestling, Acrobatics, Athletics, W.P. Blunt, W.P. Sword, W.P. Archery and Targeting; Hand to Hand: Martial Arts.', 'Shifts size at will, sees the invisible and turns invisible at will, regenerates rapidly, turns 2D4x20 dead, teleports across dimensions, climbs and swims expertly, and unleashes a devastating sonic roar.', 'All spells levels 1-3; Armor of Ithan; Fingers of wind; Fool''s gold; Tongues; Resist fire; Astral projection; Blind; Energy field; Carpet of adhesion; Magic net; Repel animals; Circle of flame; Energy disruption; Sleep; Apparition; Constrain being; Dispel magic barrier; Invulnerability; Locate; Oracle; Banishment; Amulet; Close rift', NULL, NULL, NULL, 'None - relies on natural powers', NULL, 'Playful and mischievous like all monkeys, loves pranks and acrobatics, yet careful never to truly hurt anyone.', NULL, NULL, 'A shapeshifting monkey deity who aided Vishnu''s avatar Rama; now wanders the Megaverse investigating Brahma''s secretive Nether World dealings.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.131-132');
  'kali', 'Kali', NULL, 'Goddess of Death', 'rifts', 'Deity', '18th level ley line walker and warrior, 8th level temporal wizard', 18, 'Diabolic', NULL, '20 feet (6 m)', '8 tons', '{"IQ":22,"ME":28,"MA":24,"PS":45,"PP":24,"PE":26,"PB":23,"Spd":66}', 2200, 5000, 72000, 2500, 300, NULL, 17, '{"attacks":10,"initiative":4,"strike":11,"parry":8,"dodge":8,"pull":3,"roll":3}', '+12 save vs horror factor; +30 to S.D.C. damage; +7 save vs magic; +8 save vs psionics; M.D.C. 14,400 on Rifts Earth; Murderous Whispers: telepathic command to attack a target, save vs magic 12-16 depending on relationship to target, or subject attacks for 1D4 melee rounds on a failed save.', NULL, 'Magically knows all languages; all weapon proficiencies.', 'Nightvision, sees the invisible, rapid mass bio-regeneration, turns and animates hundreds of dead, teleports self and dimensionally, immune to fire, resists other energy damage.', 'All spells levels 1-15 (18th level); All temporal spells (8th level)', 'All sensitive powers; P.P.E. shield; Hypnotic suggestion', NULL, NULL, 'The Demonblade (evil-aligned rune-like sword, 2D6x10 M.D., doubled vs good alignment, 10,000 M.D.C., regenerates, demonfire blast, flame aura); Demon''s Head (severed demon lord''s head, 1,000 M.D.C., casts Agony/Befuddle/Domination/Fireball/Mute/Fear at will, bites and can trap a victim)', NULL, 'A psychopathic, bloodthirsty sadist who tortures and kills indiscriminately, feared even by other evil beings.', 'Splugorth (as their second-in-command); Ereshkigal (Babylonian death goddess); Hel (Nordic death goddess)', 'Hindu demons (the Asuras); Parvati', 'A six-armed, three-eyed goddess born from Parvati''s battle-rage against demons; now a treacherous Splugorth lieutenant hunting her former divine allies.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.132-134');
  'kubera', 'Kubera', NULL, 'God of Greed', 'rifts', 'Deity', '12th level earth warlock', 12, 'Miscreant', NULL, '5 feet (1.5 m)', '400 lbs (180 kg)', '{"IQ":24,"ME":20,"MA":15,"PS":35,"PP":17,"PE":23,"PB":12,"Spd":33}', 600, 1000, 20000, 1500, 200, NULL, 13, '{"attacks":5,"strike":3,"parry":4,"dodge":4,"roll":4}', '+20 to S.D.C. damage; +5 save vs horror factor; +5 save vs magic; +4 save vs psionics; M.D.C. 4,000 on Rifts Earth.', NULL, 'All technical, rogue, and math skills at 98%; W.P. Sword; magically knows all languages.', 'Nightvision, sees the invisible, rapid bio-regeneration, teleports self and dimensionally.', 'All earth elemental spells', 'All sensitive powers', NULL, NULL, 'Dozen-plus greater rune weapons stolen from the gods'' hoard (per Rifts Atlantis); favors the enslaver and impaler swords', 'Vast hoard of stolen gems, jewels and rune weapons (no fixed value given)', 'Vain, greedy, and cowardly; flaunts stolen wealth and prefers theft or trickery to a fair fight.', NULL, 'Indra; Varuna (both opposed his return to the pantheon)', 'Also called Vaisravana and Jambhala, a dwarfish god of wealth who defected from the demons to guard the pantheon''s treasury, then fled with its riches in the Splugorth invasion.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.134-135');
  'yama', 'Yama', NULL, 'King of the Dead', 'rifts', 'Deity', '13th level ley line walker and necromancer', 13, 'Diabolic', NULL, '10 feet tall (3 m)', '400 lbs (180 kg)', '{"IQ":21,"ME":22,"MA":19,"PS":50,"PP":20,"PE":26,"PB":9,"Spd":88}', 1000, 2000, 30000, 2200, 900, NULL, 17, '{"attacks":7,"initiative":3,"strike":6,"parry":7,"dodge":7,"pull":2,"roll":2}', '+35 to S.D.C. damage; +9 save vs horror factor; +7 save vs magic; +5 save vs psionics; M.D.C. 6,000 on Rifts Earth.', NULL, 'All technical skills at 98%; magically knows all languages; W.P. Sword, W.P. Blunt, W.P. Archery and Targeting, W.P. Energy Rifles, W.P. Energy Heavy.', 'Nightvision, sees and turns invisible, rapid bio-regeneration, immune to poison and disease, animates and controls vast numbers of dead, teleports self and dimensionally.', 'All spells levels 1-15; All necromantic spells', 'All healing and physical powers; Empathic transmission; Mind block auto-defense; Group mind block; Psi-sword; Mind bolt; Electrokinesis', NULL, NULL, 'Yama''s Great Mace (3D4x10 M.D.); The Noose of Yama (+3 to strike, fully binds a helpless target); Yama''s Bull (demonic mount, 600 M.D.C.)', NULL, 'A cold, sadistic assassin who enjoys torture and killing, especially targeting demigods and lesser divine beings.', 'Mictla (secret ally, former ruler of Hades, see Rifts Conversion Book One); other rulers of Hades (non-aggression pact)', 'Gods of Light; champions of good', 'A once-benevolent death god turned corrupt killer, ruling part of Hades and secretly plotting with Mictla against Hades'' current overlord Modeus.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.135-136');
  'vritra', 'Vritra', NULL, 'The Obstructor', 'rifts', 'Demon Lord', '12th level water warlock', 12, 'Diabolic', NULL, '30 feet (9 m) tall, 60 feet (18.3 m) long', '25 tons', '{"IQ":20,"ME":18,"MA":15,"PS":55,"PP":24,"PE":21,"PB":6,"Spd":38}', 500, 1500, 20000, 1600, 660, NULL, 16, '{"attacks":6,"initiative":3,"strike":6,"parry":6,"dodge":6,"roll":4}', '+9 save vs horror factor; +9 save vs magic; +9 save vs psionics; M.D.C. 10,000 on Rifts Earth; Spd 66 (45mph/72km) swimming; Aura of Misery: 100 P.P.E. withers plants in a 300 ft radius, or 1000 P.P.E. for a 100-mile magic drought lasting 1D4 weeks.', '[{"name":"Demon Lore","pct":98},{"name":"Faerie Lore","pct":98},{"name":"Basic Math","pct":98},{"name":"Climbing","pct":98},{"name":"Swimming","pct":98},{"name":"Language: Dragonese/Elven","pct":98}]', 'Speaks 32 additional, unnamed languages from Earth and the Palladium world.', 'Nightvision, sees the invisible, keen senses, tracks by smell, turns invisible, breathes without air, bio-regenerates, animates dead, teleports; can wither plants and cause magical droughts.', 'All elemental water spells', 'All sensitive, physical, and super psionic powers', NULL, NULL, 'None - relies on natural powers', NULL, 'Cruel, bitter, and envious of every god, driven by a desire to destroy those more powerful than himself.', NULL, 'Indra (long-standing rival)', 'A golden, wingless dragon-god obsessed with revenge against Indra after being killed and then resurrected by loyal followers.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.136');
  'ravana', 'Ravana', NULL, 'King of Raksashas', 'rifts', 'Demon Lord', '15th level sorcerer, diabolist and summoner', 15, 'Diabolic', NULL, '30 feet (9 m) tall', '10 tons', '{"IQ":24,"ME":28,"MA":26,"PS":60,"PP":28,"PE":30,"PB":6,"Spd":88}', 2000, 6000, 80000, 7000, 1600, NULL, 17, '{"attacks":9,"initiative":4,"strike":13,"parry":10,"dodge":10,"roll":3}', '+10 save vs horror factor; +9 save vs magic; +8 save vs psionics; M.D.C. 30,000 on Rifts Earth; bodyguard of 2D6 Raksashas at all times, army of 1,000 Raksashas, can summon 3D6 Asurkan / 2D6 Baal-rogs / 2D6 Gallu Bulls or Gargoyles.', NULL, 'All weapon proficiencies, rogue, technical, and science skills at 98%; magically knows all languages.', 'Nightvision, sees and turns invisible, turns to mist, rapid bio-regeneration, animates and controls dead, teleports self and dimensionally, healing touch, resists fire and cold, shapeshifts into any form.', 'All spells levels 1-15; All circles, symbols and wards', 'All psionic powers', NULL, NULL, NULL, NULL, 'Arrogant, vengeful, and lecherous; a cunning strategist with charm enough to seduce despite his monstrous true form.', 'Kansa (mutual non-interference, no trust); Kobera and Kumbakarna (brothers)', 'The gods, especially Brahma''s and the Vedic pantheons', 'A twenty-armed, five-headed demon lord and archenemy of the Hindu pantheon; defeated once by Rama but rebuilt his body and army in Hades.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.137-138');
  'kansa', 'Kansa', NULL, 'The Arch-Demon', 'rifts', 'Greater Demon', '11th level sorcerer', 11, 'Diabolic', NULL, '7 feet tall (2.1 m)', '500 lbs (225 kg)', '{"IQ":17,"ME":15,"MA":16,"PS":60,"PP":21,"PE":23,"PB":6,"Spd":55}', 500, 2000, 25000, 3000, 700, NULL, 15, '{"attacks":7,"initiative":3,"strike":9,"parry":6,"dodge":8,"roll":3}', '+9 save vs horror factor; +9 save vs magic; +8 save vs psionics; M.D.C. 11,000 on Rifts Earth; Spd 110 (75mph/120km) flying; can assemble an army of 2,000+ lesser demons and 300 greater ones (mostly baal-rogs).', NULL, 'All wilderness, espionage, and rogue skills at 98%; magically knows all languages.', 'Nightvision, sees and turns invisible, leaps great distances, rapid bio-regeneration, animates and controls dead, teleports self and dimensionally.', 'All spells levels 1-10; Anti-magic cloud; Summon entity; Close rift; Id barrier; Dimensional portal', 'All sensitive powers; Mind block auto-defense', NULL, NULL, 'Access to several rune weapons (unspecified); prefers hand-to-hand and magic', NULL, 'A harsh, paranoid tyrant who tortures underlings for any excuse; his demons nonetheless respect his brutal rule.', NULL, 'Krishna', 'A reincarnated demon overlord and old nemesis of Krishna, rebuilt and trained by fellow asuras for centuries to seek revenge.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.138-139');
  'kumbakarna', 'Kumbakarna', NULL, 'The Giant', 'rifts', 'Greater Demon', '12th level warrior', 12, 'Miscreant', NULL, '50 feet tall (15.2 m)', '50 tons', '{"IQ":15,"ME":14,"MA":14,"PS":70,"PP":19,"PE":24,"PB":2,"Spd":66}', 700, 5000, 60000, 100, NULL, NULL, 16, '{"attacks":9,"initiative":2,"strike":4,"parry":8,"dodge":2,"roll":2}', '+8 save vs horror factor; +5 save vs magic; immune to psionics; M.D.C. 30,000 on Rifts Earth; Breath of Wind: 3D6 M.D., 50% chance of knockdown, range 500 ft (152 m).', NULL, 'W.P. Knife, W.P. Sword, W.P. Blunt.', 'Nightvision, sees the invisible, rapid bio-regeneration, resists energy damage, immune to fire and psionics; breathes a hurricane-force wind blast that can knock enemies down.', NULL, NULL, NULL, NULL, 'None - relies on natural abilities and whatever is at hand', NULL, 'Mindlessly ravenous upon waking, devouring anything edible before calming into a still-savage, violent temperament.', 'Ravana (brother)', NULL, 'A slumbering demon giant, brother to Ravana, who wakes ravenously hungry and destructive until sated, then returns to enchanted sleep.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.140-141');
  'shiva', 'Shiva', 'Creearg the First', 'The Annihilator', 'rifts', 'Modified Neuron Beast', 'Equal to an 8th level ley line walker and mind melter', 8, 'Aberrant', NULL, '22 feet tall', '1 ton', '{"IQ":30,"ME":26,"MA":25,"PS":50,"PP":24,"PE":26,"PB":2,"Spd":66}', 600, 1800, 1873, 900, 400, NULL, 15, '{"attacks":10,"initiative":4,"strike":7,"parry":9,"dodge":9,"roll":4}', '+35 to S.D.C. damage; +6 save vs horror factor; +9 save vs magic; +4 save vs psionics.', '[{"name":"Language: Dragonese/Elven","pct":98},{"name":"Language: American","pct":98},{"name":"Language: Hindu","pct":98}]', 'All wilderness, rogue, and mechanical skills (unspecified percentage).', 'Superior long-range vision, sees the invisible, hovers and floats, immune to normal fire, resists energy damage, rapid regeneration including limbs, limited teleportation.', 'All spells levels 1-7; Metamorphosis: human; Minor curse; Negate magic; Protection circle: simple; Banishment; Control/enslave entity; Mystic portal; Summon shadow beast; Remove curse', 'Total recall; Telepathy; Empathy; Object read; See aura; See the invisible; Sense evil; Sense magic; Bio-manipulation; Empathic transmission; Group mind block; Mind block auto-defense; Mentally possess others; Mind bolt; Mind bond; P.P.E. shield; Psi-sword', NULL, NULL, 'None', NULL, 'A calculating political manipulator who plays followers against each other and kills any who defy him.', 'Devy''Orhal (secret alien master)', NULL, 'A neuron beast who renamed himself after a Hindu god to found a false pantheon in India, secretly serving the imprisoned alien Devy''Orhal.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.144-145');
  'devyorhal', 'Devy''Orhal', NULL, 'The True Power', 'rifts', 'Alien Intelligence', 'Equal to a 10th level sorcerer, warlock and shifter', 10, 'Diabolic', NULL, '20 feet (6 m) tall, 30 feet (9 m) long and wide', '30 tons', '{"IQ":31,"ME":30,"MA":28,"PS":50,"PP":20,"PE":33,"PB":5,"Spd":90}', 2000, 5000, 65000, 15000, 600, NULL, 18, '{"attacks":9,"initiative":2,"strike":6,"parry":8,"dodge":8,"roll":2}', '+35 to S.D.C. damage; +10 save vs horror factor; +7 save vs magic; +8 save vs psionics; can create 6 essence fragments and bond to unlimited witches.', NULL, 'Magically literate/fluent in all languages at 98%; otherwise not applicable.', 'Nightvision, sees and turns invisible, immune to fire and cold, resists energy damage, bio-regenerates, can create bound essence fragments and empower chosen servants.', 'All magical spells; All elemental spells; All necromantic incantations (all at 10th level)', 'All sensitive powers; Psi-sword; Mind block auto-defense', NULL, NULL, 'None', NULL, 'A contemptuous, sadistic exploiter who manipulates weaker beings purely to torment and eventually destroy them.', 'Shiva the Annihilator/Creearg (agent); the Evil Immortals (unwitting pawns)', NULL, 'An imprisoned alien intelligence manipulating neuron beasts to build ley-line temples that could free it and let it seize part of India.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.145-146');
  'odin', 'Odin', NULL, 'The All-Father', 'rifts', 'Deity', '20th level ley line walker, diabolist, shifter, necromancer and temporal wizard', 20, 'Anarchist with some leanings toward good/unprincipled', NULL, '7 to 24 feet (2.1 to 7.3 m)', 'Varies with size', '{"IQ":35,"ME":34,"MA":21,"PS":43,"PP":21,"PE":29,"PB":15,"Spd":88}', 2600, 6000, 86000, 10000, 500, NULL, 15, '{"attacks":8,"initiative":3,"strike":5,"parry":10,"dodge":10,"pull":4,"roll":4}', '+28 to S.D.C. damage; +10 save vs horror factor; +8 save vs magic; +10 save vs psionics; M.D.C. 17,200 in the Rifts world; Horror Factor 18 when enraged; Spd 294 (200mph/321km) flying in eagle form; can summon 4D6 Valkyries per minute and field an army of 10,000+; automatic 60% on any untrained skill.', '[{"name":"Horsemanship","pct":98}]', 'All domestic, wilderness, and espionage skills at 98%; boxing, wrestling, W.P. Blunt, W.P. Sword, W.P. Spear, W.P. Energy Rifle; Hand to Hand: Martial Arts plus Boxing.', 'Keen far-sight, sees and turns invisible, knows all languages, teleports freely, immune to disease/heat/cold, turns hordes of dead, shapeshifts into any form, needs no food or air.', 'All spell magic of all levels; Spells of legend; Temporal magic; Circles; Wards; Rune magic; All Necromantic spells (per Rifts Africa)', 'All sensitive and healing powers', NULL, NULL, 'Enchanted Chain Mail (2,000 M.D.C., lightweight); Gungnir the Spear (greatest rune weapon, 3D6x10 M.D., True Strike never misses, Weapon Breaker, dimensional travel powers); Draupnir the ring (copies itself every 9th night, +2 save vs magic, mind block, +2 vs horror factor); Odin''s Magical Throne (scries the Megaverse like a crystal ball)', NULL, 'Guarded and mysterious in disguise, otherwise jovial and boastful; turns coldly, murderously furious when angered.', 'Thor; Njord; Tyr; other gods of the Norse pantheon; sometimes Loki; Valkyries; Warriors of Valhalla', 'Norse giants and giants in general; dragons; the Fenrir Wolf; vampires; supernatural monsters and intelligences', 'The supreme, fickle war-and-magic god of Asgard, obsessed with the coming apocalypse Ragnarok and secretly driven by pride and lust for worship.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.146-148');
  'sleipnir', 'Sleipnir', NULL, 'Odin''s Horse', 'rifts', 'Supernatural Horse (unique)', NULL, NULL, 'Anarchist', NULL, NULL, NULL, '{"IQ":11,"ME":20,"MA":16,"PS":50,"PP":23,"PE":24,"PB":18,"Spd":120}', 500, 500, 2000, NULL, NULL, NULL, NULL, '{"attacks":4,"initiative":2,"strike":6,"parry":6,"dodge":7}', '+6 to save vs horror factor, +8 to save vs magic and psionics; also runs through open air at Spd 220 (150 mph/240 km).', NULL, NULL, 'Supernatural speed and strength; runs through the air as flight; leaps 50 ft high or 100 ft long from a standing start; bio-regenerates 1D6x10 M.D.C. every five minutes.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Odin''s eight-legged supernatural steed, born when Loki (in mare form) mated with a giant''s horse; extremely fast and can run on open air.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.148');
  'tyr', 'Tyr', 'Tyr Odinson', 'God of Justice', 'rifts', 'Deity', '15th level warrior, 8th level sorcerer', 15, 'Principled (but violent, brutal and deadly)', NULL, '6 to 24 feet (1.8 to 7.3 m)', 'Varies with size', '{"IQ":26,"ME":30,"MA":20,"PS":40,"PP":25,"PE":26,"PB":17,"Spd":22}', 1500, 3500, 50000, 1800, 75, NULL, 15, '{"attacks":5,"initiative":3,"strike":7,"parry":11,"dodge":11,"roll":9}', 'M.D.C. 10,000 on Rifts Earth. +25 to S.D.C. damage; +10 to save vs horror factor; +7 to save vs magic; +9 to save vs psionics; three attacks per melee if using magic instead of five hand to hand.', '[{"name":"Wilderness Survival","pct":98},{"name":"Detect Ambush","pct":80},{"name":"Track (Humanoids)","pct":80},{"name":"Pilot Boats: Ships and Sail Types","pct":90},{"name":"Swim","pct":90},{"name":"Language: Old Norse","pct":98},{"name":"Language: Dragonese/Elf","pct":98}]', 'Athletics, wrestling, W.P. Sword, W.P. Blunt, W.P. Spear; Hand to Hand: Expert.', 'Nightvision 200 ft; sees the invisible; invulnerable to cold; bio-regenerates 2D6x10 M.D.C. per minute; teleport 85%, dimensional teleport 80% (known dimensions only).', 'Knows all spells from levels 1-8', 'Mind block; Sixth sense', NULL, NULL, 'The Silver Spear (greater rune weapon, I.Q. 12, telepathically linked to Heimdall, 2D6x10 M.D., thrown range 1000 ft and returns, casts invulnerability/fire ball/impervious to energy/call lightning/minor curse/mystic portal 3x/day at 11th level); Axe of Justice (indestructible, 6D6 M.D., returns when thrown, range 500 ft)', NULL, 'Grim and ferociously determined; neither pleas nor threats sway him; serves as judge, jury and executioner among the gods.', 'Odin (during Ragnarok)', 'Giants; Dragons; Evildoers', 'One-handed Norse war god and brother of Thor, also called Tiw; sacrificed his hand binding the Fenrir Wolf and now guards Asgard as an enforcer of law.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.149');
  'thor', 'Thor', NULL, NULL, 'rifts', 'Deity', '20th level warrior', 20, 'Anarchist with a temper', NULL, '7 to 24 feet (2.1 to 7.3 m)', '500 lbs (225 kg)', '{"IQ":14,"ME":27,"MA":18,"PS":60,"PP":24,"PE":30,"PB":18,"Spd":88}', 1650, 4000, 56500, 250, 400, NULL, 15, '{"attacks":7,"initiative":5,"strike":7,"parry":12,"dodge":12,"pull":9,"roll":9}', 'M.D.C. 11,300 on Rifts Earth. P.S. 70 and damage bonus becomes +55 M.D. when wearing the Belt of Might; M.D. lightning/electrical attacks do only 1/4 damage to him; four attacks per melee if using magic; vulnerable: a called shot (-4) to an old whetstone wound in his skull does 100 M.D. and imposes -2 attacks/strike/parry/dodge, lost initiative, -20% skills for 3D4 rounds.', '[{"name":"Language: Old Norse","pct":98},{"name":"Language: Dragonese/Elf","pct":98}]', 'All domestic, physical and wilderness skills at 85%; all ancient W.P.s; Hand to Hand: Martial Arts.', 'Nightvision 200 ft; sees invisible; invulnerable to fire and cold; M.D. lightning/electricity do only 1/4 damage; bio-regenerates 1D4x100 M.D.C. per minute; weather effects at no P.P.E. cost: circle of rain, rain dance, summon storm, energy disruption (20th level).', 'None (dislikes magic intensely)', 'All physical powers (10th level)', NULL, NULL, 'Magic Chain Mail (1000 M.D.C., lightweight); Mjolnir, Thor''s War-Hammer (indestructible, 4D6x10 M.D., +55 M.D. with Belt of Might, double damage to giant races/gargoyles/supernatural predators/dragons/alien intelligences, throw range 2000 ft and returns, 4x/day auto-hit throw, calls lightning 2D6x10 M.D. range 1000 ft); Megingiord, Belt of Might (doubles wearer''s P.S.; on Thor raises P.S. to 70 and makes his S.D.C. damage bonus mega-damage); Iarn Greiper, Iron Gloves (let him wield the hammer/belt safely, squeeze/crush 2D6x10 M.D., let wearer hold opposing-alignment rune weapons without harm)', NULL, 'Loyal and friendly to warriors he respects; dislikes magicians on principle; becomes furious when tricked and lets fly with his hammer.', 'Odin; other Norse gods', 'Giants; evil intelligences', 'God of thunder and lightning, son of Odin, and protector of Asgard; historically the most popular and physically strongest Norse war god.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.150-152');
  'magni', 'Magni', 'Magni Thorson', 'God of Strength', 'rifts', 'Deity (young)', '10th level warrior', 10, 'Unprincipled', NULL, '7 feet (2.1 m)', '400 lbs (180 kg, all muscle)', '{"IQ":14,"ME":20,"MA":18,"PS":79,"PP":22,"PE":30,"PB":18,"Spd":77}', 1000, 1400, 24000, 100, 70, NULL, 12, '{"attacks":5,"initiative":3,"strike":6,"parry":10,"dodge":10,"pull":4,"roll":3}', 'M.D.C. 4,800 on Rifts Earth. +60 to S.D.C. damage; horror factor rises to 16 when he demonstrates his strength; +9 to save vs magic; +9 to save vs poison and disease; +4 to save vs psionics; twice normal carrying/lifting capacity (200x P.S. = 15,800 lbs); throws objects 3x normal distance; leaps 100 ft.', '[{"name":"Cook","pct":85},{"name":"Fishing","pct":90},{"name":"Tracking","pct":75},{"name":"Wilderness Survival","pct":80},{"name":"Climbing","pct":80},{"name":"Prowl","pct":75},{"name":"Language: Old Norse","pct":98},{"name":"Language: Dragonese/Elf","pct":98}]', 'Athletics, boxing, wrestling, W.P. Sword, W.P. Knife, W.P. Blunt; Hand to Hand: Martial Arts.', 'Sees the invisible; bio-regenerates 3D4x10 M.D.C. per minute; invulnerable to cold/heat; doubled carrying and lifting capacity; leaps 100 ft.', NULL, 'All physical powers', NULL, NULL, 'None; relies on his natural powers and his wits', NULL, 'Young and naive despite centuries of age, often unaware of his own great strength; gentler than most Norse warrior gods but can turn violent.', NULL, NULL, 'Thor''s young son and supposedly the strongest Norse god, famed for lifting a giant''s body off his trapped father as a child.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.152');
  'heimdall', 'Heimdall', NULL, 'The Guardian', 'rifts', 'Deity', '14th level man at arms', 14, 'Scrupulous', NULL, '10 to 30 feet (3 to 9 m)', 'Varies with size', '{"IQ":17,"ME":25,"MA":16,"PS":35,"PP":23,"PE":26,"PB":18,"Spd":50}', 500, 1000, 25000, 70, 600, NULL, 14, '{"attacks":6,"initiative":8,"strike":6,"parry":12,"dodge":12,"pull":4,"roll":4}', 'M.D.C. 5,000 on Rifts Earth. Cannot be attacked from behind or by surprise; +20 to S.D.C. damage; +12 to save vs horror factor; +7 to save vs magic; +5 to save vs psionics; automatically senses magic/supernatural evil within a 1 mile radius.', '[{"name":"Astronomy","pct":75},{"name":"Land Navigation","pct":98},{"name":"Wilderness Survival","pct":98},{"name":"Language: Dragonese/Elf","pct":98},{"name":"Language: Old Norse","pct":98},{"name":"Language: Atlantean","pct":98}]', 'Pilot sail and rowboats, athletics, boxing and wrestling, W.P. Sword, W.P. Spear; Hand to Hand: Martial Arts plus boxing.', 'Nightvision 2000 ft; hawk-like vision to 20 miles; sees invisible; exceptional hearing (-70% to prowl against him); tracks/recognizes by smell; immune to cold, poison, disease; bio-regenerates 4D6x10 M.D.C./minute; turns 2D4x100 dead; teleport self 65%, dimensional teleport to Asgard 90%.', NULL, 'Empathy; Telepathy; Presence sense; Sixth sense; Total recall; Mind block auto-defense; Mind bolt; Psi-shield; Psi-sword; Telekinesis: super; Telekinetic force field; (plus standard psi-stalker senses)', NULL, NULL, 'Enchanted Chain Mail (1000 M.D.C., lightweight, silent, impervious to fire and cold); Heimdall''s Sword (greater rune broadsword, indestructible, I.Q. 12, scrupulous, 1D6x10 M.D. double vs supernatural monsters/giants/dragons/vampires; casts impervious to energy/invulnerability/constrain being/dispel magical barriers/negate magic/call lightning/fire ball 3x/24hr at 10th level)', NULL, 'Very solemn and humorless, dedicated to guarding the rainbow bridge Bifrost; has no patience for Loki''s jokes.', NULL, 'Loki', 'Warrior god who guards Bifrost, the rainbow bridge linking Asgard to other dimensions; an ancient rival of Loki.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.152-154');
  'loki', 'Loki', NULL, 'God of Deceit', 'rifts', 'Deity', '15th level ley line walker and shifter; 8th level warrior', 15, 'Miscreant', NULL, '6 feet (1.8 m) in human form, 24 feet (7.3 m) in god form', '300 lbs (135 kg) human form, 900 lbs (405 kg) god form', '{"IQ":28,"ME":25,"MA":22,"PS":35,"PP":25,"PE":28,"PB":21,"Spd":40}', 2100, 4200, 63000, 8000, 900, NULL, 12, '{"attacks":5,"initiative":2,"strike":9,"parry":8,"dodge":8,"pull":4,"roll":4}', 'M.D.C. 12,600 on Rifts Earth. +20 to S.D.C. damage; +10 to save vs horror factor; +11 to save vs magic; +10 to save vs psionics; three attacks per melee if using magic instead of five physical/psionic.', NULL, 'All Domestic, Espionage, Rogue and Wilderness skills at 96%; W.P. Knife, W.P. Sword, W.P. Pistol, W.P. Energy Rifle; Hand to Hand: Assassin (8th level).', 'Nightvision 200 ft; sees invisible; turns invisible at will; bio-regenerates 3D6x10 M.D.C. per minute; shapeshifts into any animal indefinitely; teleport and dimensional teleport 96%; magically knows all languages.', 'All spell magic levels 1-12; All summoning spells/circles; Sanctum; Talisman; Restoration; Close rift; Dimensional portal', 'All sensitive, physical and healing powers', NULL, NULL, 'Assorted magic potions, scrolls, and guardian statues; Splugorth Enslaver (see Rifts Atlantis p.130); A Sword of Atlantis (I.Q. 15, telepathically linked to Loki, evil alignment burns good-aligned touchers 1D4x10 M.D., teleport: lesser/greater, mystic portal, time hole, sanctum 3x/24hr at 10th level; double dragon heads breathe fire 1D6x10 M.D./force 2D4x10 M.D./lightning 1D6x10 M.D., double vs vampires or alien intelligences)', NULL, 'Outwardly friendly and charming, subtly insulting; a master of lies who turns childishly angry and dangerous when thwarted.', 'Several Norse gods; Goquas', 'Heimdall', 'Complex trickster god of deceit, a member of the Aesir despite plaguing them; both trusted schemer and habitual betrayer of the gods.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.154-156');
  'balder', 'Balder', 'Balder Odinson', 'the Noble', 'rifts', 'Deity', '15th level warrior, 10th level ley line walker and mind melter', 15, 'Scrupulous', NULL, '6 to 24 feet (1.8 to 7.3 m)', 'Varies with size', '{"IQ":25,"ME":25,"MA":25,"PS":38,"PP":26,"PE":24,"PB":26,"Spd":66}', 2000, 3400, 54000, 4500, 600, NULL, 13, '{"attacks":6,"initiative":4,"strike":8,"parry":11,"dodge":11,"pull":3,"roll":3}', 'M.D.C. 10,800 on Rifts Earth. Also written Baldr. +23 to S.D.C. damage; +14 to save vs horror factor; +6 to save vs magic; +6 to save vs psionics; three attacks per melee if using magic.', '[{"name":"Detect Ambush","pct":92},{"name":"Detect Concealment","pct":92},{"name":"Wilderness Survival","pct":92},{"name":"Swim","pct":92},{"name":"Climb","pct":92},{"name":"Pilot Boats: All","pct":92},{"name":"Tracking","pct":92},{"name":"First Aid","pct":92},{"name":"Language: Dragonese/Elf","pct":98},{"name":"Language: Old Norse","pct":98}]', 'Hand to Hand: Martial Arts.', 'Nightvision 1000 ft; sees invisible; heat and cold do half damage; bio-regenerates 1D6x10 M.D.C. per minute; teleport 88%, dimensional teleport 70% (known dimensions only).', 'Knows all spells from levels 1-15', 'All physical and healing powers; Psi-sword; Psi-shield; P.P.E. shield; Empathic transmission; Group mind block', NULL, NULL, 'Balder''s Earth Blade (greatest holy weapon; remove curse 50% chance; 4D6+6 M.D., triple to evil-aligned targets; expels demons 89%/44%; circle of protection)', NULL, 'Warm-hearted, sympathetic, compassionate and generous; a heroic fighter unafraid of death who avoids foolish risks.', 'Freyr; spirits of light; all good Norse gods', 'The forces of darkness', 'Most beloved and morally upright Norse god, killed by Loki''s trickery and later returned to life by Hel at Odin''s demand.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.156-157');
  'hel-norse', 'Hel', NULL, 'Goddess of Death', 'rifts', 'Deity', '18th level ley line walker', 18, 'Diabolic', NULL, '6 to 30 feet (1.8 to 9 m)', 'Varies with size', '{"IQ":29,"ME":30,"MA":21,"PS":30,"PP":25,"PE":30,"PB":25,"Spd":30}', 2600, 5500, 81000, 7000, 1000, NULL, 15, '{"attacks":6,"initiative":1,"strike":11,"parry":8,"dodge":6,"roll":3}', 'M.D.C. 16,200 on Rifts Earth. +15 to S.D.C. damage; +11 to save vs horror factor; +9 to save vs magic; +9 to save vs psionics; those failing a horror-factor save of 17+ are filled with despair; three attacks per melee if using magic. Special Death Touch once per melee: +4D6 direct to Hit Points (1D4x10 M.D. to M.D.C. beings), halves victim''s attacks and combat bonuses for 1D6 rounds. Secretly having Splugorth bio-wizards build her a new Murex Metzla-like body (currently 5,000 M.D.C., planned 90,000 M.D.C.) to approach the Mechanoids as an ally.', NULL, 'All science, rogue and technical skills at 98%; W.P. Sword, W.P. Energy Pistol, W.P. Energy Rifle, robot combat: elite; Hand to Hand: Assassin.', 'Nightvision 1000 ft; sees invisible; invulnerable to cold, disease, poison; fire/energy do half damage; bio-regenerates 3D6x10 M.D.C. per minute; teleport 85%, dimensional teleport 75% (known dimensions only).', 'All magic spells levels 1-15; All necromantic spells (no necromancer O.C.C. powers)', 'All sensitive and physical powers', NULL, NULL, 'None; relies on her magic and natural abilities', NULL, 'Arrogant, cunning, secretive and cruel; enjoys inflicting pain and hopes to become the universe''s supreme being.', 'Two Splugorth lords; Mictla the Devourer', 'Odin; Thor; Balder; most Aesir and Vanir gods; the Gods of Light', 'Goddess who rules the realm of the dead; secretly plots with Splugorth bio-wizards to build a new body and ally with the Mechanoids.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.157-158');
  'njord', 'Njord', NULL, 'God of the Seas', 'rifts', 'Deity', '14th level air and water warlock', 14, 'Anarchist', NULL, '6 to 24 feet (1.8 to 7.3 m)', 'Varies with size', '{"IQ":23,"ME":22,"MA":22,"PS":40,"PP":20,"PE":22,"PB":17,"Spd":33}', 1000, 1300, 23000, 3000, 300, NULL, 14, '{"attacks":4,"initiative":1,"strike":5,"parry":7,"dodge":7,"pull":3,"roll":5}', 'M.D.C. 4,600 on Rifts Earth. +25 to S.D.C. damage; +8 to save vs horror factor; +5 to save vs magic; +5 to save vs psionics; three attacks per melee if using magic; summons storms/fog (20th level, 3x/day, no P.P.E. cost), an iceberg (1x/day, oceans only) and dispels fog (2x/day), all at no P.P.E. cost.', '[{"name":"Fishing","pct":90},{"name":"Pilot Boats: All","pct":90},{"name":"S.C.U.B.A.","pct":90},{"name":"Climbing","pct":90},{"name":"Language: Old Norse","pct":98},{"name":"Language: Dragonese/Elf","pct":98},{"name":"Language: American","pct":98},{"name":"Language: Euro","pct":98}]', 'Athletics, wrestling, W.P. Sword, W.P. Spear, W.P. Blunt, W.P. Pistol, W.P. Automatic Rifle, W.P. Energy Rifle; Hand to Hand: Basic.', 'Nightvision 1000 ft; sees invisible; hawk-like vision; invulnerable to cold; needs no air to breathe; swims 98%; bio-regenerates 1D6x10 M.D.C. per minute.', 'All air and water spells, equal to a 14th level warlock', 'All sensitive powers; Hydrokinesis', NULL, NULL, 'Sea Spear (magical, 2D4x10 M.D., can be thrown underwater or on land and returns, range 1000 ft)', NULL, 'Fairly laid back for a Norse god; distant and condescending toward humans generally, but friendly to sailors and sea explorers; dislikes environmentalists.', NULL, NULL, 'Vanir god of the seas and former husband of the giantess Skadi; a legendary sailor who later built a modern shipping empire.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.158-159');
  'freyr', 'Freyr', NULL, 'God of the Sun and Rain', 'rifts', 'Deity', '12th level warrior and sorcerer', 12, 'Principled', NULL, '6 to 24 feet (1.8 to 7.3 m)', 'Varies with size', '{"IQ":21,"ME":24,"MA":22,"PS":35,"PP":23,"PE":25,"PB":24,"Spd":63}', 1200, 3000, 42000, 4000, 800, NULL, 12, '{"attacks":6,"initiative":4,"strike":6,"parry":9,"dodge":9,"pull":3,"roll":3}', 'M.D.C. 8,400 on Rifts Earth. Also known as Frey and Fricco. +20 to S.D.C. damage; +8 to save vs horror factor; +6 to save vs magic; +6 to save vs psionics; two attacks per melee if using magic; parries/deflects laser beams; creates a globe of daylight at no P.P.E. cost.', '[{"name":"Holistic Medicine","pct":98},{"name":"Wilderness Survival","pct":90},{"name":"Sing and Dance","pct":90},{"name":"Language: Old Norse","pct":98},{"name":"Language: Egyptian","pct":98},{"name":"Language: Greek","pct":98},{"name":"Language: German","pct":98},{"name":"Language: Dragonese/Elf","pct":98}]', 'W.P. Sword, W.P. Blunt; Hand to Hand: Martial Arts.', 'Nightvision 200 ft; sees invisible; invulnerable to fire, heat and cold; bio-regenerates 3D6x10 M.D.C. per minute; teleport 75%, dimensional teleport 70% (known dimensions only).', 'All spells levels 1-10; Anti-magic cloud; Remove curse; Calm storms; Protection circle: superior; Sanctum; Close rift', 'All sensitive, physical and healing powers', NULL, NULL, NULL, NULL, 'Honorable, fair-minded and friendly even toward mortals; prefers negotiation to combat but is respected for his bravery.', 'Balder; Apollo; Marduk; Isis', NULL, 'Peace-loving Vanir god of sun, rain and crops, son of Njord; the only Asgardian who actively works with other Pantheons of Light.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.159-160');
  'freya', 'Freya', NULL, 'Goddess of Love and Beauty', 'rifts', 'Deity', '10th level ley line walker and 6th level valkyrie', 10, 'Unprincipled', NULL, '6 to 24 feet (1.8 to 7.3 m)', 'Varies with size', '{"IQ":27,"ME":23,"MA":30,"PS":21,"PP":23,"PE":26,"PB":30,"Spd":23}', 850, 2000, 28500, 2000, 200, NULL, 11, '{"attacks":3,"initiative":1,"strike":5,"parry":6,"dodge":6,"pull":2,"roll":2}', 'M.D.C. 5,700 on Rifts Earth; a potion of Eros'' design has temporarily halved these to 14,250 and 3,850 (wearing off over roughly 10 years). +6 to S.D.C. damage; +7 to save vs horror factor; +7 to save vs magic; +5 to save vs psionics; two attacks per melee if using magic; while cursed she cannot tolerate any male but her brother Freyr and will attack them; with the Brisingamen worn, +4 to all saves, pull punch, dodge and called shots.', '[{"name":"Dance","pct":98},{"name":"Sing","pct":98},{"name":"Play the Flute","pct":98},{"name":"Language: Dragonese/Elf","pct":98},{"name":"Language: Old Norse","pct":98},{"name":"Language: Greek","pct":98}]', 'Other languages known via magic; Hand to Hand: Basic.', 'Nightvision 100 ft; sees invisible; invulnerable to cold; bio-regenerates 1D4x10 M.D.C. per minute; teleport 75%, dimensional teleport 50%.', 'Spells levels 1-6; Life drain; Second sight; Hallucination; Minor curse; Sickness; Curse: luck; Curse: phobia; Wards', 'All sensitive powers', NULL, NULL, 'The Brisingamen (golden necklace, currently stolen by Hera; aura of fertility within 10 miles while worn; +4 to saves, pull punch, dodge and called shots while worn)', NULL, 'Direct and lusty, not a mistress of seduction; blunt about her desires; currently cursed to hate and fear all men but her brother.', NULL, 'Ishtar; Aphrodite; Sifter; Hera', 'Freyr''s twin sister and Norse goddess of love, currently cursed by Hera to loathe men after an affair with Zeus was discovered.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.160-161');
  'yggdrasil', 'Yggdrasil', NULL, 'The World Tree', 'rifts', 'Magic Tree / Megaversal Landmark (unique)', NULL, NULL, 'Scrupulous', NULL, '20,000 feet (6100 m) tall', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'M.D.C. by Location: Leaf Stem 10; Leaf 100 each; Twig (wand) 600 each; Small Branch (cane/staff) 1200 each; Medium Branch (large staff) 3000 each; Large Branch 10,000 each; Giant Branch 40,000 each; Main Body/Trunk 500,000, regenerates 1D4x1000 per minute.', NULL, NULL, 'Powers like those of the Millennium Trees (Rifts England); rarely grants gifts; offers the perilous Gift of Knowledge ritual - nine days bound to the tree for deep magical insight, at grave risk of death or madness.', NULL, NULL, NULL, NULL, NULL, NULL, 'Aloof and unresponsive to nearly everyone; ignores priests, kings and even gods, rewarding only a rare, major favor.', NULL, NULL, 'The colossal, possibly-sentient tree linking the nine worlds of the Norse pantheon; thought to be the ancestor of the Millennium Trees.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.161-162');
  'midgard-serpent', 'The Midgard Serpent', NULL, NULL, 'rifts', 'Unique Monster (dragon-like)', NULL, NULL, 'Diabolic', NULL, '1000 feet (305 m) long, 15 to 60 feet (4.6 to 18.3 m) wide', NULL, '{"Spd":33}', 10000, 30000, 120000, NULL, NULL, NULL, 19, '{"attacks":7,"initiative":1,"strike":6,"dodge":1}', '+11 to save vs horror factor; +10 to save vs psionics and magic; immune to mind control and possession; regenerates 1D6x100 M.D.C. per minute; anyone within 600 ft of the struggle risks being struck by its coils (+1 to strike, 1D4x10 M.D.).', NULL, NULL, 'Regenerates 1D6x100 M.D.C. per minute; sees invisible; immune to magical or psionic control and possession; whips or ensnares prey with its prehensile tail and tongue.', NULL, NULL, NULL, NULL, NULL, NULL, 'Territorial and savage; guards Yggdrasil''s roots jealously and devours any who disturb the tree, especially noisy intruders.', NULL, 'Thor (fated to kill and be killed by each other at Ragnarok)', 'An enormous dragon-like serpent dwelling at Yggdrasil''s roots, fated by myth to slay Thor with poison during Ragnarok.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.162-163');
  'hrungnir', 'Hrungnir', NULL, 'A Leader of the Norse Giants & Champion', 'rifts', 'Norse Giant (unique champion)', '15th level warrior', 15, 'Aberrant', NULL, '32 feet tall (9.6 m)', '12 tons', '{"IQ":12,"ME":24,"MA":21,"PS":60,"PP":23,"PE":27,"PB":7,"Spd":66}', 400, 1000, 18000, 100, NULL, NULL, 15, '{"attacks":5,"initiative":4,"strike":10,"parry":7,"dodge":7,"roll":3}', 'M.D.C. 4,000 on Rifts Earth (or 1000 S.D.C. and 400 H.P.). +45 to S.D.C. damage; +8 to save vs horror factor; +6 to save vs magic; +6 to save vs psionics.', NULL, 'Hand to Hand: Assassin.', 'Nightvision 600 ft; resistant to cold and heat (half damage); bio-regenerates 1D6x10 M.D.C. per minute.', NULL, NULL, NULL, NULL, 'Magical Chain Mail (1000 M.D.C.); Hrungnir''s Whetstone (magical stone hammer, requires P.S. 30, -2 to hit vs targets under 12 ft tall, 1000 M.D.C. and regenerates 1D4x100 M.D.C./minute, 4D6x10 M.D., thrown range 1000 ft and returns); Hrungnir''s Stone Shield (enchanted stone slab, 3000 M.D.C. regenerates 1D6x10 M.D.C./minute, +3 to parry, parries missiles/energy weapons at no penalty, +4 to save vs spells)', NULL, 'A mean but honorable warrior; considers Thor a cowardly traitor and is obsessed with revenge against him and the Asgardians.', 'His resurrected clay giant golem; many giant warriors', 'Thor; the Asgardians', 'A resurrected Norse giant champion who once nearly killed Thor in a duel; has hidden for a thousand years plotting revenge.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.163-164');
  'hrungnirs-clay-giant', 'Hrungnir''s Clay Giant', NULL, NULL, 'rifts', 'Construct / Golem (Creature of Magic)', 'Equal to a 12th level warrior', 12, 'Aberrant', NULL, '30 feet tall (9 m)', '20 tons', '{"IQ":6,"ME":10,"MA":14,"PS":60,"PP":20,"PE":30,"PB":4,"Spd":20}', NULL, NULL, 20000, NULL, NULL, NULL, 15, '{"attacks":4,"initiative":2,"strike":6,"parry":5,"dodge":5,"roll":3,"damage":45}', '+10 to save vs magic, +10 to save vs psionics; impervious to horror factor; alt (non-M.D.C. worlds): 2,500 S.D.C. instead of 20,000 M.D.C.', NULL, 'W.P. Blunt. No other skills. Combat Skills: Hand to Hand: Assassin.', 'Sees the invisible; magically regenerates 1D6x100 M.D.C. every five minutes.', NULL, NULL, NULL, NULL, 'None; may uproot trees and use them as clubs or spears', NULL, 'Mostly mindless; attacks anyone resembling humans or the Gods of Asgard, but rarely speaks.', 'Hrungnir (creator); Any giant monster (20ft+) posing as a Norse giant or enemy of Asgard', 'The Norse gods (destroyed it once)', 'Golem-like giant built by giant sorcerers to match Hrungnir''s strength; recently reawakened, it now wanders attacking anyone it mistakes for Asgardians.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.165');
  'fenrir', 'Fenrir', NULL, NULL, 'rifts', 'Unique Monster (Giant Wolf)', 'Intelligent Animal', NULL, 'Diabolic', NULL, '12 feet (3.6 m) high, 30 feet (9 m) long', '15 tons', '{"IQ":18,"ME":24,"MA":18,"PS":60,"PP":24,"PE":26,"PB":10,"Spd":100}', NULL, NULL, 60000, 200, NULL, NULL, 18, '{"attacks":6,"initiative":4,"strike":7,"parry":8,"dodge":8,"roll":6}', '+11 to save vs horror factor; immune to all magic and psionic attacks (rune weapons and hi-tech M.D. weapons still do full damage); alt (non-M.D.C. worlds): 4,000 S.D.C. and 2,000 hit points instead of 60,000 M.D.C.', NULL, 'Skills of Note: None. Combat Skills: Natural.', 'Night vision 1000ft, sees the invisible, hawk-like vision; resistant to fire and cold (half damage); bio-regenerates 1D4x100 M.D.C./minute; immune to magic and psionics.', NULL, NULL, NULL, NULL, NULL, NULL, 'Feral and insane with frustration from captivity; has the temperament of a rabid animal.', NULL, NULL, 'Giant wolf, son of Loki, bound for millennia by dwarven magic; prophesied to kill Odin at Ragnarok. Also called Fenris.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.165-166');
  'wothan', 'Wothan', 'Wothancrellyth', 'the Slayer', 'rifts', 'Alien Intelligence (Splugorth)', '11th level ley line walker and psionic', 11, 'Miscreant', NULL, '25 feet (7.6 m) in diameter, 12 ft (3.6 m) tall', '45 tons', '{"IQ":24,"ME":27,"MA":23,"PS":47,"PP":20,"PE":27,"PB":4,"Spd":50}', NULL, NULL, 60000, 12000, 4000, NULL, 17, '{"attacks":11,"initiative":3,"strike":5,"parry":5,"dodge":-1,"roll":1,"damage":32}', '+8 to save vs magic, +8 to save vs psionics; alt: 5 psionic attacks or 2 magic attacks per melee instead of 11 physical; M.D.C. by location: Giant Eye 1200, Eye Film Cover 2000, Protective Eye Spines (6) 500 each, Main Tentacles (5) 800 each, Secondary Tentacles (6) 500 each; main body (60,000 M.D.C.) must be reduced to -4000 to destroy; vulnerable: silver and magic weapons do triple damage.; Minions: Thorg the Mighty and Loki, plus a band of Kydians', NULL, 'Intelligence, swimming, climbing, advanced math, land navigation all 98%; demon and faerie lore 81%.', 'Nightvision 1000ft, superior color vision, sees invisible, bio-regenerates, regrows limbs (72 hrs), needs no air, dimensional teleport 98%, possession, teleport self 600 miles, healing touch, restoration, resurrection, stone to flesh, remove curse, summons 2D6 minions.', 'All spells levels 1-15; Create magic tattoos', 'All sensitive, healer, and super psionic powers', NULL, NULL, NULL, NULL, 'Sociopathic and vengeful toward his own kind, but genuinely loyal to the few servants who stayed with him.', 'Only one: a Goqua who calls himself Loki (Loki-G)', 'A rival Splugorth; Most other Splugorth; Odin and the Gods of Asgard', 'A deposed Splugorth lord, once ruler of a vast dimensional empire, now a hidden refugee posing as the Norse god Wothan.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.170-171');
  'thorg', 'Thorg', 'Thorg Glnn', 'the Mighty', 'rifts', 'Kydian Powerlord', '8th level powerlord', 8, 'Anarchist', NULL, '10 ft tall (3 m)', '650 lbs (295 kg)', '{"IQ":11,"ME":16,"MA":15,"PS":40,"PP":21,"PE":21,"PB":10,"Spd":33}', NULL, NULL, 400, 30, NULL, 18, 10, '{"attacks":6,"initiative":2,"strike":5,"parry":8,"dodge":8,"roll":5,"pull":3,"damage":25}', '+6 to save vs horror factor, +6 to save vs magic, +6 to save vs psionics; M.D.C. 400 (bio-tech borg conversion) plus living armor with 500 M.D.C.; alt (non-M.D.C. worlds): 220 S.D.C., 72 hit points, armor A.R. 18 / 400 S.D.C.; horror factor modified down to look more human-like.', NULL, 'Standard Overlord/Powerlord training: basic math 98%, radio: basic 80%, prowl 65%, wilderness survival 90%, swim 90%, boxing, wrestling, gymnastics, W.P. Blunt, W.P. Sword, W.P. Energy Pistol, W.P. Energy Rifle, W.P. Energy Heavy. Combat Skills: Hand to Hand: Assassin.', 'Eyes of Eylor: nightvision 600ft, telescopic vision 6000ft at 300x magnification, sees aura, sees invisible, senses magic and P.P.E.; half damage from radiation/heat; bio-regenerates 1D4x10 M.D.C./hour.', NULL, NULL, NULL, NULL, 'Dragon Thunderer Hammer (greatest rune weapon, indestructible, 1D4x10 M.D. plus thunderclap, thrown 300ft, returns); Eylor helm of omnipotence; Eylor hunter-seeker eye; Staff of power; Two suits of Powerlord armor; Plasma sword (2D6 M.D.); Double blade plasma axe (3D6 M.D.); K-E4 plasma ejector (6D6 M.D.); A dozen K-1000 spider defense systems', NULL, 'Outgoing and jovial for a Kydian, imitates Thor with a merry disposition; loves contests of strength.', 'Wothan (master); Several Knights of Camelot (deceived into believing him a demigod)', NULL, 'A heavily augmented Kydian powerlord kept alive for a thousand years by Wothan''s bio-wizardry, serving as his chief enforcer disguised as a Viking warrior.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.171-172');
  'loki-g', 'Loki-G', NULL, NULL, 'rifts', 'Goqua (Shapeshifter)', 'Equal to a 10th level sorcerer', 10, 'Aberrant', NULL, '8 ft tall (2.4 m), 20 ft long (6 m); human shape: 6 ft 4 in (1.93 m)', 'Two tons; 200 lbs (90 kg) in human shape', '{"IQ":27,"ME":30,"MA":26,"PS":25,"PP":22,"PE":22,"PB":9,"Spd":80}', NULL, NULL, 6000, 900, 800, NULL, 18, '{"attacks":7,"initiative":1,"strike":5,"parry":6,"dodge":6,"roll":2,"damage":10}', '+15 to save vs horror factor, +6 to save vs magic, +10 to save vs psionics; P.B. 22 in human form; alt: 5 magic attacks per melee instead of 7 physical/psionic.', NULL, 'All Espionage 98%. Combat Skills: Natural.', 'Impervious to poisons/drugs/gases, turns invisible at will, bio-regenerates 1D4x10 M.D.C./minute, understands/reads/speaks all languages, cannot be possessed or mind-controlled.', 'Knows ALL ritual/circle and spell invocations, levels 1-15', 'All sensitive powers; Meditation; Empathic transmissions; Mind block auto-defense; Hypnotic suggestion; Hydrokinesis; Mind bolt', NULL, NULL, 'Light environmental armor (40 M.D.C., posing as Atlantean sorcerer); Vibro-sword; Black assassin armor (110 M.D.C., posing as Sunaj assassin); Lesser rune sword; Various magic items and energy weapons', NULL, 'Evil, scheming trickster who toys with mortal and divine lives purely for his own entertainment.', 'Wothan (nominal); Thorg (nominal); Fellow Goqua in the American southwest', NULL, 'A Goqua shapeshifter who has impersonated the Norse trickster god Loki since 952 A.D., now conspiring with Wothan while playing his own games.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.172-173');
  'woden', 'Woden', NULL, 'the Hangman', 'rifts', 'Vampire Intelligence', '10th level mind melter, 9th level wizard', 10, 'Aberrant', NULL, '120 feet (36.5 m) in diameter', '50 tons', '{"IQ":26,"ME":28,"MA":20,"PS":40,"PP":27,"PB":2,"Spd":7}', 1000, NULL, 4000, 1200, 200, NULL, 18, '{"attacks":8,"initiative":6,"strike":7,"parry":6,"dodge":6,"roll":1}', '+8 to save vs magic, +8 to save vs psionics; sneak attacks not possible; cannot be blinded and may attempt to parry all attacks; impervious to mind control and psionic/magic sleep and paralysis; alt: 3 attacks by psionics or magic instead of 8 hand to hand; M.D.C. by location: Small Eyes (100) 5 each, Giant Eye 300, Tentacles (10) 100 each, Main Body 4000; sunlight reduces all its powers by 75% (50% if overcast).', NULL, 'Understands all languages; demon and monster lore 98%; W.P. Sword. Combat Skills: Natural.', 'Creates vampires, nightvision 4000ft, sees invisible/infrared/UV, smells blood 2 miles away, speaks all languages, regenerates hit points and M.D.C. each melee, invulnerable except to magic, wood, silver, running water, and holy water.', 'All summoning and circle magic; Close rift; Dimensional portal; Mystic portal; Teleport: superior; Time hole; Restoration; Calm storm; Dispel magic barrier; Negate magic; Anti-magic cloud; Create magic scroll; Constrain being; Agony; Invulnerability; Sleep; Circle of flame; Armor of Ithan; Resist fire; Telekinesis; Blinding flash; Thunderclap', 'All sensitive and healing powers; Empathic transmission; Group mind block; Hypnotic suggestion; Psi-shield; Psi-sword', NULL, NULL, NULL, NULL, 'Cunning even for a vampire intelligence, willing to cooperate with other creatures; dreams of a world where vampires rule and all others are cattle.', 'The Sowki A''Lattreen (Thor the Warrior) and his mercenary band; His vampire legion', NULL, 'A vampire intelligence posing as the Norse god Woden/Odin to build a cult and army in war-torn Russia and Romania.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.173-174');
  'balders-ghost', 'Balder''s Ghost', 'Franz Devlin', NULL, 'rifts', 'Master Vampire (human origin)', '8th level master vampire, first level shifter', 8, 'Diabolic', NULL, '6 feet, 1 inch (1.85 m)', '170 lbs (76.5 kg)', '{"IQ":21,"ME":18,"MA":25,"PS":30,"PP":22,"PE":20,"PB":21,"Spd":31}', 130, NULL, NULL, 82, 160, 13, 14, '{"attacks":6,"initiative":3,"strike":5,"parry":6,"dodge":6,"roll":3,"damage":15}', '+5 to save vs horror factor, +7 to save vs magic, +2 to save vs psionics; impervious to mind control; M.D.C.: Armor or Magic (no innate M.D.C.); Hit Points 130 as a vampire; Spd 31 running (50/34 mph bat form, 58/40 mph wolf form); Franz cannot learn new spells or advance as a shifter.', NULL, 'Monster and demon lore 94%, wilderness survival 90%, W.P. Sword, W.P. Energy Pistol, W.P. Energy Rifle, W.P. Heavy Energy; speaks Euro 98%, American 75%, Dragonese/Elf 65%. Combat Skills: Natural vampire abilities.', 'Controls other vampires, shapeshifts into wolf/vampire bat/mist, summons vermin, invulnerable to normal weapons, regenerates 2D6 hit points/melee, nightvision 1600ft, smells blood 1 mile away, does not breathe, recognizes other vampires by sight.', 'Several summoning circles; All first level spell magic; Concealment; Fear; Circle of flame; Magic net; Constrain being; Create mummy; Luck curse', 'Death trance; Alter aura (self); Empathy; Mind block; Presence sense; Sense evil; Deaden pain; Induce sleep; Super hypnotic suggestion', NULL, NULL, 'Ancient chain mail (A.R. 13, 44 S.D.C.); Metal sword, carried for show (1D8+15 S.D.C.)', NULL, 'A mesmerizing, egotistical public speaker; a former megalomaniac human who still craves prestige despite serving his vampire master.', 'His vampire legion', NULL, 'Franz Devlin, an evil cultist turned master vampire, poses as the ghost of the Norse god Balder to build a following for Woden.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.174-175');
  'thor-the-warrior', 'Thor', 'A''Lattreen', 'The Warrior', 'rifts', 'Sowki (alien mercenary)', '7th level ley line walker', 7, 'Miscreant', NULL, '7 feet tall (2.1 m)', '300 lbs (136 kg)', '{"IQ":20,"ME":17,"MA":22,"PS":34,"PP":17,"PE":16,"PB":7,"Spd":14}', NULL, NULL, 150, 220, 24, NULL, 14, '{"attacks":5,"initiative":1,"strike":4,"parry":4,"dodge":4,"roll":6,"damage":17}', '+1 to save vs magic, +1 to save vs psionics; alt: 3 magical attacks per melee instead of 5 physical.', NULL, 'Demon and monster lore 91%, basic and advanced math 98%, palming 76%, concealment 88%, W.P. Sword, W.P. Spear, W.P. Energy Rifle, W.P. Heavy Energy, athletics, acrobatics, boxing, wrestling. Combat Skills: Natural.', 'Hawk-like vision (2 miles), nightvision 600ft, third eye sees the invisible, magically knows and understands all languages.', 'All illusionary spell and ritual magic; Death trance; Concealment; Detect concealment; Charismatic aura; Multiple images; Horrific illusion; Apparition; Mask of deceit; Hallucination; Metamorphosis: animal; Metamorphosis: human; Summon lesser beings', 'Meditation; Mind block; Sense magic; Speed reading; Summon inner strength; Total recall; Object read; Hypnotic suggestion', NULL, NULL, 'Gladiator armor modified to resemble Viking armor (70 M.D.C.); Vibro-sword (2D6 M.D.); Several energy pistols and rifles; Techno-Wizard hammer (6D6 M.D. powered, thrown 100ft, returns via psionic remote)', NULL, 'A skillful leader and diplomat who plays a mythological paladin persona; a fine tactician secretly planning to profit from Woden''s war.', 'Freya (a succubus); His band of interdimensional mercenaries; Woden', NULL, 'A three-eyed reptilian Sowki mercenary who disguises himself as the Norse god Thor using illusion and metamorphosis magic.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.175-176');
  'zurvan', 'Zurvan', NULL, 'God of Time', 'rifts', '4-Dimensional Being / God', '20th level temporal wizard and ley line walker', 20, 'Unknown (an indifferent anarchist, not bound by mortal morals)', NULL, 'Any shifting shape; occasionally a humanoid 10 to 100 feet tall (3 to 30.5 m)', 'Varies with size and form', '{"IQ":28,"ME":30,"MA":18,"PS":35,"PP":24,"PE":30,"PB":18,"Spd":220}', NULL, NULL, 80000, 8000, 2400, NULL, 18, '{"attacks":8,"strike":9,"parry":11,"dodge":11,"roll":5,"damage":20}', 'Always has the initiative and can never be surprised or attacked from behind; +16 to save vs horror factor, +11 to save vs magic, +8 to save vs psionics (practically invulnerable); alt: 4 attacks by psionics or magic instead of 8 hand to hand; alt (non-M.D.C. worlds): 6,000 S.D.C. and 3,000 hit points instead of 80,000 M.D.C.; P.B. 18 in human form.', NULL, 'Skills are meaningless for this entity; can perform any activity at 90% proficiency. Combat Skills: Natural.', 'Impervious to illusions, poison, disease, heat/cold, mind control, and possession; steps in/out of the 3rd dimension at will (invulnerable while out of phase), passes through walls, sees all spectrums, bio-regenerates 2D6x10 M.D.C./melee, teleports and time/space warps at will.', 'All temporal magic; All spells levels 1-15; Several temporal magic spells unique to 4-D beings', 'All sensitive abilities; Detect psionics; Psychic diagnosis; Psychic surgery; Deaden pain; Mind block auto-defense; P.P.E. shield; Telemechanics', NULL, NULL, NULL, NULL, 'Unnaturally cool and detached, seemingly distracted even in conversation; rarely interferes in mortal or divine affairs.', 'Brahma (Hindu deity)', NULL, 'Ancient four-dimensional being, father of Ahura Mazda and Ahriman and perhaps one of the Old Ones; arguably the mightiest god still active anywhere.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.177-178');
  'ahura-mazda', 'Ahura Mazda', NULL, NULL, 'rifts', 'Deity (Persian Pantheon)', '20th level ley line walker and mind melter', 20, 'Scrupulous good', NULL, '6 to 26 feet (1.8 to 7.9 m) tall', 'Varies with size', '{"IQ":29,"ME":27,"MA":30,"PS":34,"PP":19,"PE":26,"PB":25,"Spd":88}', NULL, NULL, 77000, 10000, 4000, NULL, 15, '{"attacks":6,"initiative":4,"strike":6,"parry":5,"dodge":5,"roll":4,"pull":6,"damage":19}', '+14 to save vs horror factor, +7 to save vs magic, +7 to save vs psionics; Horror Factor is 15 (awe, good alignment), 17 (selfish), or 18 (evil); alt: 3 attacks by magic instead of 6; M.D.C. reduced to 15,400 on Rifts Earth; alt (non-M.D.C. worlds): 7,700 S.D.C. and 2,000 hit points; also called Mazda, Lord Mazda, and Ohrmazd.; Minions: can summon 1D6 Spirits of Light each hour, or gather an army of 1D4x100', NULL, 'Knows all skills he cares to use at 94%; magically knows all languages. Combat Skills: Hand to Hand: Basic.', 'Nightvision 1000ft, sees invisible, hawk-like vision to 20 miles, knows all languages, teleport 96%/dimensional teleport 94%, impervious to heat/fire/cold/poison/disease/possession, bio-regenerates 1D4x100 M.D.C./minute, restores lost limbs and eyes.', 'All spells levels 1-15, including the spells of legend, at 20th level', 'All sensitive, physical, healing, and super psionic abilities, equal to a 20th level mind melter', 'Eyes of Ahura Mazda (holds vampires/undead at bay like a holy symbol); Beam of Retribution (1D4x100 M.D. to evil characters, reveals alignment and truthfulness, negates illusions)', NULL, 'Psi-sword (16D6 M.D. or quick roll 2D4x10+20 M.D.; half damage to good, double to evil); Sword of Truth (greatest rune weapon: 4D6 M.D. to mortals, 1D6x10 to demons, 1D6x100 to gods/alien intelligences; I.Q. 14, indestructible); Robe of Stars (4000 M.D.C., can teleport/dimensionally teleport the wearer)', NULL, 'Kindly, wise, fair and compassionate; loved and trusted by most, feared by the guilty.', 'Ra and Isis (Egyptian pantheon)', 'All forces of evil, especially vampires and alien intelligences; Ahriman (his arch-nemesis)', 'Chief god of the Persian pantheon, embodiment of good, son of Zurvan and twin of the evil Ahriman; protector of mortals across the Megaverse.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.178-182');
  'asha', 'Asha', NULL, 'Truth', 'rifts', 'Deity (Amesha Spenta, Persian Pantheon)', '15th level man at arms, 10th level ley line walker and fire warlock', 15, 'Scrupulous good', NULL, '6 to 26 feet (1.8 to 7.9 m) tall', 'Varies with size', '{"IQ":20,"ME":25,"MA":28,"PS":45,"PP":27,"PE":23,"PB":28,"Spd":88}', NULL, NULL, 12300, 2500, 700, NULL, 12, '{"attacks":7,"initiative":6,"strike":8,"parry":11,"dodge":11,"roll":3,"pull":5,"damage":30}', '+12 to save vs horror factor, +5 to save vs magic, +6 to save vs psionics; Horror Factor 15 to evil characters/deceivers; Spd 220 (150 mph/241 km) flying; alt: 2 attacks by magic instead of 7; M.D.C. 2,600 on Rifts Earth; alt (non-M.D.C. worlds): 900 S.D.C. and 430 hit points; also known as Vahishta and Ardavahisht.', NULL, 'Prowl, detect ambush, wilderness survival, holistic medicine, swimming, climbing, boxing, all lore, all at 97%; magically knows all languages; W.P. Knife, W.P. Sword, W.P. Blunt, W.P. Energy Rifle. Combat Skills: Hand to Hand: Martial Arts.', 'Nightvision 200ft, sees invisible, turns invisible at will, knows all languages, flies, teleport 89%/dimensional teleport 64%, bio-regenerates 1D4x100 M.D.C./minute, impervious to possession and mind control.', 'All spells levels 1-5; Dispel magic barrier; Negate magic; Id barrier (10th level ley line walker); All elemental fire spells (10th level warlock)', 'All sensitive and physical powers', 'True Sight (sees a being''s true shape at all times; can force a disguised being to reveal itself; gods must save vs magic 16+)', NULL, 'Magic Plate Mail (2000 M.D.C.); Asha''s Holy Sword (turn 4D6 dead 80%, healing touch 2D6 S.D.C./hit points or M.D.C., 6D6+6 M.D. double vs diabolic alignment, expel devils/demons 89%/44%)', NULL, 'Serene, cool, and given to laughter; incensed by deception and behaves like an idealistic, old-fashioned superhero.', 'All good deities of other pantheons; Champions of light', 'All demons, evil gods, and forces of darkness, especially deceivers', 'Son of Ahura Mazda, preserver of order and enemy of demons and deceivers; travels the Megaverse hunting evil tricksters.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.181-182');
  'vohu-manah', 'Vohu Manah', NULL, 'Good Mind', 'rifts', 'Deity (Amesha Spenta, Persian Pantheon)', '15th level ley line walker', 15, 'Principled', NULL, '6 to 26 feet (1.8 to 7.9 m) tall', 'Varies with size', '{"IQ":29,"ME":27,"MA":29,"PS":24,"PP":16,"PE":20,"PB":21,"Spd":55}', NULL, NULL, 10000, 2000, 1000, NULL, 12, '{"attacks":4,"strike":2,"parry":3,"dodge":5,"pull":4,"roll":4,"damage":9}', '+8 to save vs horror factor, +4 to save vs magic, +7 to save vs psionics; alt: 2 attacks by magic instead of 4; M.D.C. 2,000 on Rifts Earth; alt (non-M.D.C. worlds): 700 S.D.C. and 300 hit points; also known as Vahman.', NULL, 'All domestic, demon/monster lore, faerie lore, intelligence, tracking, sing, dance, and art, all at 98%; knows all languages magically. Combat Skills: Hand to hand: Basic.', 'Nightvision 200ft, sees invisible, speaks all languages, bio-regenerates 1D4x100/minute, resistant to fire/heat/cold, turns 1D4x100 dead, teleport 73%/dimensional teleport 60%.', 'All spells levels 1-6; Dispel magic barrier; Invulnerability; Globe of silence; Mute; Purification; Exorcism; Protection circle: simple; Wards; Anti-magic cloud; Amulet; Close rift; Id barrier; Impenetrable wall of force', 'All sensitive powers', 'Sense Disposition (knows a being''s true alignment on sight; disguises revealed unless save vs magic 16+); Gaze of Harmony (forces combatants in line of sight to stop fighting for 2D4 rounds unless they save vs magic 16+)', NULL, 'Scepter of Magic (greatest rune weapon, I.Q. 15, casts negate magic/remove curse/speed of the snail/anti-magic cloud/impenetrable wall of force 3x/24hrs at 10th level; 1D6x10 M.D. as a weapon); Diadem of Knowledge (any skill at 98% 3x/day, reads runes/wards/enchantments at 88%, casts a 20th level spell 4x/day)', NULL, 'Compassionate, analytical diplomat; his once-impeccable judgement is being eroded by manufactured suspicion of non-humans.', 'Ahura Mazda (father); His siblings; Champions of goodness and peace', 'The forces of evil and war', 'First-born son and chief advisor of Ahura Mazda, spreads the Persian faith and mediates disputes for his father.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.182-183');
  'armaiti', 'Armaiti', 'Spenta Armaiti', 'Devotion', 'rifts', 'Deity (Amesha Spenta, Persian Pantheon)', '18th level Ley Line Walker and 15th level Mind Melter', 18, 'Scrupulous', NULL, '6 to 26 feet tall (1.8 to 7.9 m)', 'Varies with size', '{"IQ":26,"ME":22,"MA":28,"PS":20,"PP":19,"PE":21,"PB":27,"Spd":45}', NULL, NULL, 9600, 2500, 1200, NULL, 15, '{"attacks":7,"initiative":3,"strike":4,"parry":7,"dodge":7,"roll":3,"pull":3,"damage":3}', '+8 to save vs horror factor, +4 to save vs magic, +5 to save vs psionics; alt: 2 attacks by magic instead of 7 (prefers psionics); M.D.C. 1,920 on Rifts Earth; alt (non-M.D.C. worlds): 600 S.D.C. and 320 hit points; also known as Spendarmard; Experience Level: 18th level ley line walker and 15th level mind melter.', NULL, 'All domestic skills, wilderness survival, detect ambush, all lore, basic and advanced math, art and writing, all at 98%. Combat Skills: Hand to hand: Martial Arts.', 'Nightvision 200ft, sees invisible, speaks all languages, bio-regenerates 1D4x100 M.D.C./minute, impervious to mind control/possession, resistant to fire/cold, turns 2D6x100 dead, teleport 89%/dimensional teleport 76%; shares Vohu Manah''s pacification power.', 'All level 1-4 spells; Sleep; Tongues; Eyes of Thoth; Call lightning; Cure illness; Heal wounds; Purification; Water to wine; Remove curse; Anti-magic cloud', 'All sensitive and super powers', 'Gift of Conversion (a vision that may let an evil/selfish character reconsider their path; save vs psionics)', NULL, 'Psi-sword (14D6 M.D. or quick roll 2D4x10 M.D.)', NULL, 'Kind, motherly, and calm; rarely angers, appearing disappointed rather than furious even in battle.', 'Her family; Champions of light', 'Ahriman and the forces of evil and war', 'Eldest daughter of Ahura Mazda, goddess of devotion who inspires faith and can offer wayward mortals a chance to change their ways.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.183-184');
  'sharevar', 'Sharevar', NULL, 'Order/Control', 'rifts', 'Deity (Amesha Spenta, Persian Pantheon)', '15th level earth warlock and 9th level stone master', 15, 'Scrupulous good', NULL, '7 to 26 feet tall (2.1 to 7.9 m)', 'Varies with size', '{"IQ":24,"ME":26,"MA":26,"PS":40,"PP":22,"PE":26,"PB":17,"Spd":88}', NULL, NULL, 10000, 2000, NULL, NULL, 15, '{"attacks":6,"initiative":5,"strike":6,"parry":9,"dodge":9,"roll":3,"pull":3,"damage":25}', '+9 to save vs horror factor, +7 to save vs magic, +7 to save vs psionics; alt: 2 attacks by magic instead of 6; M.D.C. 2,000 on Rifts Earth; alt (non-M.D.C. worlds): 700 S.D.C. and 300 hit points; also known as Khsathra Vairya; Psionic Knowledge: None.', NULL, 'All technical and science skills, plus carpentry, land navigation, and wilderness survival, all at 98%; magically knows all languages; W.P. Spear, W.P. Targeting. Combat Skills: Hand to hand: Martial Arts.', 'Nightvision 200ft, sees invisible, speaks all languages, bio-regenerates 1D4x100 M.D.C./minute, resistant to fire/cold, teleport self 88%/dimensional teleport 63%.', 'All elemental earth spells; All stone magic, including gem powers', NULL, 'Metal Blasts (6D6 M.D. molten metal bolt that burns/distracts target: no initiative, -1 combat skills, -10% skills for 1D4 rounds; double vs supernatural evil/elementals; range 1000ft)', NULL, 'Enchanted Plate Mail Armor (2000 M.D.C., regenerates 1D4x100 M.D.C./hour); Spear of Justice (greatest rune weapon, I.Q. 13, 2D4x10 M.D. to most/2D4x100 M.D. vs Ahriman & supernatural intelligences, thrown 2000ft and returns, casts call lightning/energy field/dispel magic barrier/negate magic 3x/24hrs at 10th level); Sharevar''s Shield (indestructible, +3 to parry, parries energy beams at -2)', NULL, 'Cool and withdrawn, speaking little except to render judgment; deadly and professional in combat.', 'His family; Champions of light', 'Ahriman and the forces of evil and chaos', 'Son of Ahura Mazda, god of metal, stone, and order; built the pantheon''s pyramid and quietly monitors the magical upheaval on Rifts Earth.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.184-185');
  'haurvatat', 'Haurvatat', NULL, 'Wholeness', 'rifts', 'Deity', '12th level water warlock, 4th level ley line walker', 12, 'Scrupulous', NULL, '7 to 26 feet tall (2.1 to 8 m)', 'Varies with size', '{"IQ":22,"ME":24,"MA":27,"PS":18,"PP":18,"PE":24,"PB":24,"Spd":50}', 300, 600, 9000, 2000, 300, NULL, 12, '{"attacks":5,"initiative":2,"strike":4,"parry":6,"dodge":6,"roll":2,"pull":2,"damage":2}', '+2 to S.D.C. damage; +7 save vs horror factor, +6 vs magic, +6 vs psionics; M.D.C. reduced to 1,800 on Rifts Earth.', '[{"name":"All domestic and wilderness skills","pct":98},{"name":"Wilderness survival","pct":98},{"name":"Swim","pct":98},{"name":"Demon/monster lore","pct":98}]', 'Hand to Hand: Expert; magically knows all languages.', 'Nightvision 200 ft, sees the invisible, speaks all languages, regenerates 1D4x100 M.D.C./minute, resists fire and cold, senses whether someone''s intentions are good or bad, can summon 1D4 lesser water elementals.', 'All elemental water spells (12th level warlock); All spells levels 1-3; Astral projection; Purification; Cure illness', 'All sensitive powers', NULL, NULL, NULL, NULL, 'Seems naive and innocent, but is highly perceptive; nearly impossible to deceive.', NULL, NULL, 'Persian water goddess, daughter of Ahura Mazda, also known as Hordad; opposes demons and can sense hidden good or bad intent.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.185-186');
  'ameretat', 'Ameretat', NULL, 'Immortality', 'rifts', 'Deity', '15th level ley line walker', 15, 'Principled', NULL, '5 to 24 feet tall (1.5 to 7.3 m)', 'Varies with size', '{"IQ":23,"ME":21,"MA":26,"PS":25,"PP":21,"PE":28,"PB":24,"Spd":77}', 375, 600, 9750, 2000, 1000, NULL, 11, '{"attacks":5,"initiative":5,"strike":5,"parry":8,"dodge":8,"roll":3,"damage":7}', '+7 to S.D.C. damage; +10 save vs horror factor (rises to H.F. 16 vs undead/necromancers, causing fear instead of awe), +8 vs magic, +4 vs psionics; M.D.C. reduced to 1,951 on Rifts Earth. Special powers: Free the Damned (frees cursed undead who fail a save vs magic), Cleansing Blast (2D6x10 M.D. vs P.P.E.-feeding creatures), Resurrection (limited, once per victim).', '[{"name":"All domestic and wilderness skills","pct":98}]', 'Hand to Hand: Martial Arts; magically speaks all languages.', 'Nightvision 200 ft, sees invisible, speaks all languages, regenerates 1D6x10 M.D./minute, immune to possession/poison/disease and vampire powers, resists fire/cold, turns 4D6x100 dead, heals 6D6 by touch, teleports self/dimensionally at 61%.', 'All spells levels 1-5; Call lightning; Cure illness; Fly as the eagle; Invisibility: superior; Invulnerability; Exorcism; Negate magic; Wisps of confusion; Protection circle: simple; Remove curse; Protection circle: superior; Id barrier', 'All healing powers; Group mind block; P.P.E. shield; Hydrokinesis', NULL, NULL, NULL, NULL, 'Joyful and cheerful, replaced by sorrow when fighting evil; shows only disgust toward necromancers and evil shifters.', NULL, NULL, 'Persian goddess of plants and immortality, also known as Amurdad; heals, resurrects, and can free the undead from their curse.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.186-187');
  'verethraghna', 'Verethraghna', NULL, 'God of Victory', 'rifts', 'Deity', '18th level man at arms', 18, 'Anarchist', NULL, '7 to 26 feet tall (2.1 to 7.9 m)', 'Varies with size', '{"IQ":16,"ME":19,"MA":14,"PS":55,"PP":27,"PE":25,"PB":16,"Spd":88}', 1200, 2000, 32000, 100, 400, NULL, 14, '{"attacks":8,"initiative":5,"strike":8,"parry":13,"dodge":13,"roll":4,"pull":4}', '+4 to pull punch, +4 to roll w/ impact or fall; M.D.C. reduced to 6,400 on Rifts Earth; running speed 88 (60 mph/96 km) or flying speed 220 (150 mph/241 km).', '[{"name":"All espionage skills","pct":90},{"name":"All wilderness skills","pct":90},{"name":"Language: Dragonese/Elven","pct":98},{"name":"Language: Persian","pct":98},{"name":"Language: Akkadian","pct":98},{"name":"Language: Hindi","pct":98},{"name":"Language: American","pct":98},{"name":"Language: Atlantean","pct":98},{"name":"Language: Spanish","pct":98}]', 'Hand to Hand: Martial Arts; Boxing; all ancient W.P.s; W.P. Energy Rifle; W.P. Energy Pistol.', 'Nightvision 200 ft, regenerates fully within 24 hrs (4D6x10 M.D./min), sees invisible, immune to poison/disease, doesn''t breathe air, resists fire/cold, teleports, and shapeshifts into ten forms including wind and raven (flies in those forms).', NULL, 'All physical powers; All sensitive powers; All healing powers', NULL, NULL, 'Enchanted Plate Mail (M.D.C. 2000); The Golden Blade - Greater Rune Weapon (3D4x10 M.D.; breathes fire/force/lightning blasts, double damage to supernatural monsters)', NULL, 'A fierce, arrogant warrior who loves battle and glory and will not tolerate disrespect from mortals.', 'Gods of Light (uneasy allies)', 'Herakles (rival)', 'Persian war god, strongest of his pantheon; delights in combat and glory and can take ten different forms, including a warrior with a golden sword.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.187-188');
  'vayu', 'Vayu', NULL, 'God of the Winds', 'rifts', 'Deity', '18th level air warlock and warrior', 18, 'Unprincipled', NULL, '9 to 30 feet tall (2.7 to 9.1 m)', 'Varies with size', '{"IQ":21,"ME":20,"MA":21,"PS":40,"PP":24,"PE":25,"PB":17,"Spd":99}', 2600, 4000, 66000, 4000, 400, NULL, 15, '{"attacks":6,"initiative":5,"strike":7,"parry":10,"dodge":10,"roll":3,"damage":25}', '+3 to roll w/ impact or fall; M.D.C. reduced to 13,200 on Rifts Earth. Air form: immune to kinetic damage (incl. M.D. punches/vibro-swords) but vulnerable to energy, magic and psionics; lightning does not double damage to him unlike a true air elemental.', '[{"name":"All wilderness skills","pct":98},{"name":"Demon/monster lore","pct":98},{"name":"Art","pct":98},{"name":"Writing","pct":98},{"name":"Language: Dragonese/Elven","pct":98},{"name":"Language: Elemental","pct":98},{"name":"Language: Persian","pct":98},{"name":"Language: Hindi","pct":98}]', 'Plus 6 other languages at 98%; Hand to Hand: Martial Arts; W.P. Sword.', 'Nightvision 600 ft, sees/turns invisible at will, speaks all languages, regenerates 4D6x10 M.D./min, resists fire/heat/cold, teleports self/dimensionally, and summons/controls 1D6 minor air elementals hourly.', 'All air spells', 'All sensitive powers; Bio-manipulation; P.P.E. shield; Psi-sword', NULL, NULL, 'Spear of the Wind (1D6x10 M.D., returns when thrown, talks); Sword of Lightning - Greatest Rune Weapon (healing abilities + 1D6x10 M.D. + spell magic)', NULL, 'Severe and intimidating; demands respect and shows little regard for those he outranks.', 'Gods of Light; his elemental servants; Indra (Vedic); Soma (Vedic)', 'Ahriman; demons and evil gods; major air elemental intelligences; Gods of India, especially the Brahmanic', 'Ancient Persian wind god, older than Ahura Mazda; controls storms and lightning and can transform into a semi-elemental air form.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.188-189');
  'anahita', 'Anahita', NULL, 'Goddess of the Waters', 'rifts', 'Deity', '15th level water warlock, 12th level ley line walker', 15, 'Principled', NULL, '7 to 26 feet tall (2.1 to 7.9 m)', 'Varies with size', '{"IQ":20,"ME":20,"MA":21,"PS":26,"PP":19,"PE":22,"PB":27,"Spd":50}', 1370, 3000, 43700, 4000, NULL, NULL, 14, '{"attacks":5,"initiative":3,"strike":4,"parry":6,"dodge":6,"roll":2,"damage":11}', '+2 to roll w/ impact or fall; M.D.C. reduced to 8,740 on Rifts Earth. Special: Purification Ritual (1x/hr, cures poison/disease/curses or purifies 10 barrels of food/drink; forces lesser undead to save vs magic or be destroyed, holds back vampires/lesser demons 15 minutes).; Minions: can summon 1D6 lesser water elementals to assist her', NULL, 'Hand to Hand: Expert; all domestic and wilderness skills, plus swimming (no percentage printed); magically knows all languages.', 'Nightvision 600 ft, sees/turns invisible, swims at double speed, breathes without air, speaks all languages, regenerates 3D4x10 M.D./min, resists fire/heat/cold, teleports, summons 1D4 minor water elementals hourly.', 'All elemental water spells; All spells levels 1-8; Protection circle: simple; Water to wine; Purification; Banishment; Metamorphosis: mist; Close rift; Protection circle: superior', NULL, NULL, NULL, NULL, NULL, 'Charismatic, intelligent, and strong-willed; impatient with those careless about the environment or indecisive.', NULL, NULL, 'Persian water goddess who protects drinking water; blames humanity for pollution but will fight beside Ahura Mazda against Ahriman.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.189-190');
  'atar', 'Atar', NULL, 'God of Fire', 'rifts', 'Deity', '20th level fire warlock and 10th level ley line walker', 20, 'Anarchist', NULL, '7 to 20 feet tall (2.1 to 6.1 m); can appear in human or fiery form', 'Varies with form and size', '{"IQ":16,"ME":19,"MA":15,"PS":37,"PP":27,"PE":24,"PB":15,"Spd":88}', 1300, 2500, 38000, 5000, 600, NULL, 16, '{"attacks":6,"initiative":6,"strike":8,"parry":11,"dodge":11,"roll":3,"pull":2,"damage":22}', '+2 to pull punch, +3 to roll w/ impact or fall; M.D.C. reduced to 7,600 on Rifts Earth.; Minions: can summon 2D4 lesser fire elementals at full M.D.C., or 1D4 greater ones', '[{"name":"Detect ambush","pct":98},{"name":"Demon/monster lore","pct":98},{"name":"Faerie lore","pct":98},{"name":"Chemistry","pct":98},{"name":"Advanced math","pct":98}]', 'Hand to Hand: Martial Arts; W.P. Sword; W.P. Blunt; W.P. Energy Rifle; W.P. Energy Pistol.', 'Nightvision 120 ft, regenerates 4D6x10 M.D./min (1D6x100 if surrounded by fire), immune to fire and non-magical energy, takes half damage from physical attacks, teleports self/dimensionally.', 'All elemental fire spells; All spells levels 1-4; Energy disruption; Life drain; Exorcism; Negate magic; Oracle; Banishment; Mystic portal', 'All physical powers; Sixth sense; Empathy; Pyrokinetic blade', NULL, NULL, NULL, NULL, 'Elemental in nature, indifferent to collateral harm though not deliberately cruel; always keeps his word and seeks revenge for offenses.', 'Gods of Light (associate, not full member); Agni (Hindu fire god, his brother)', 'Demons and gods of darkness; Fire elemental intelligences and greater elementals; Asha (rival)', 'Persian fire god, semi-elemental in nature; jealous rival of Asha over dominion of fire, feared by demons and elementals alike.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.190-191');
  'haoma', 'Haoma', NULL, 'The Plant God', 'rifts', 'Deity', '15th level ley line walker and dryad', 15, 'Principled', NULL, '3 to 300 feet tall (0.9 to 91.5 m)', 'Varies with size and shape', '{"IQ":23,"ME":20,"MA":19,"PS":51,"PP":18,"PE":28,"PB":17,"Spd":44}', 2375, 4500, 68750, 6000, 600, NULL, 14, '{"attacks":4,"initiative":2,"strike":4,"parry":6,"dodge":6,"roll":2,"pull":2}', '+2 to pull punch, +2 to roll w/ impact or fall; M.D.C. reduced to 13,550 on Rifts Earth. Sense Movement in the Earth: 100 mile radius. Aura of Fertility: 1000 mile radius (cannot cause infertility). Speed is 0 while in plant form.; Minions: can summon 1D4 Earth-Tree plant elementals', '[{"name":"All wilderness skills","pct":98},{"name":"All domestic skills","pct":98},{"name":"All science skills","pct":98},{"name":"All lore","pct":98},{"name":"Holistic medicine","pct":98},{"name":"Detect ambush","pct":98}]', 'Hand to Hand: Basic; magically knows all languages.', 'Nightvision 600 ft, sees invisible, regenerates 1D4x100 M.D./min, heals 3D6 by touch, teleports self/dimensionally, and can turn into a shrub or a tree up to 300 ft tall (can sense but not attack while transformed).', 'All herbal magic; All spells levels 1-4; Calling; Energy disruption; Escape; Sleep; Impervious to energy; Stone to flesh; Water to wine; Purification; Words of truth; Exorcism; Remove curse', 'All sensitive powers; Induce sleep; Detect psionics; Psychic diagnosis; Hydrokinesis', NULL, NULL, NULL, NULL, 'Placid and unhurried; talkative once engaged, and relentless once he decides on a course of action.', 'Dionysus (Greek); Soma (Indian)', 'Forces of darkness and destruction', 'Persian plant god and protector of nature; can transform into a tree, sense movement through the earth, and bless land with fertility.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.191-193');
  'mithras', 'Mithras', NULL, NULL, 'rifts', 'Deity', '20th level ley line walker', 20, 'Scrupulous', NULL, '6 to 24 feet tall (1.8 to 7.3 m)', 'Varies with size', '{"IQ":24,"ME":27,"MA":25,"PS":51,"PP":28,"PE":30,"PB":22,"Spd":110}', 2500, 5000, 75000, 6000, 400, NULL, 14, '{"attacks":6,"initiative":4,"strike":9,"parry":11,"dodge":11,"roll":3,"pull":3}', '+3 to pull punch, +3 to roll w/ impact or fall; M.D.C. reduced to 15,000 on Rifts Earth. Special Aura: at 20th level can radiate a globe of daylight (240 ft/72 m).', '[{"name":"All science skills","pct":98},{"name":"All technical skills","pct":98},{"name":"Pilot airplane","pct":98},{"name":"Pilot helicopter","pct":98},{"name":"Pilot hover craft","pct":98},{"name":"Pilot jet aircraft","pct":98},{"name":"Pilot motorcycle","pct":98},{"name":"Horsemanship","pct":98},{"name":"Holistic medicine","pct":98},{"name":"Wilderness survival","pct":98},{"name":"Tracking","pct":98}]', 'Hand to Hand: Martial Arts; W.P. Archery and Targeting; W.P. Blunt; W.P. Sword; W.P. Energy Pistol; W.P. Energy Rifle.', 'Nightvision 1200 ft, sees/turns invisible, regenerates 1D6x100 M.D./min, invulnerable to heat/cold, resists all energy, teleports self/dimensionally.', 'All magic spells levels 1-15', 'All physical powers; Telepathy; Mind block auto-defense; P.P.E. shield; Telemechanics; Bio-manipulation', NULL, NULL, NULL, NULL, 'A skillful diplomat and patient listener who favors peaceful solutions, though he tires of endless conflict and withdraws from it.', 'Gods of Light; several pantheons across the Megaverse', 'Forces of darkness and destruction', 'Youngest son of Ahura Mazda, also called Mitras or Mitra; sun god who withdrew from the war between light and darkness to study mortals.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.193');
  'ahriman', 'Ahriman', NULL, 'The Evil One', 'rifts', 'Deity', '20th level ley line walker and necromancer', 20, 'Diabolic', NULL, '7 to 50 feet tall (2.1 to 15.2 m)', 'Varies with size', '{"IQ":23,"ME":25,"MA":22,"PS":45,"PP":23,"PE":27,"PB":20,"Spd":88}', 2660, 5200, 78600, 10000, 1200, NULL, 17, '{"attacks":7,"initiative":4,"strike":10,"parry":7,"dodge":7,"roll":3,"damage":30}', '+30 to S.D.C. damage, +3 to roll w/ impact or fall; M.D.C. reduced to 15,720 on Rifts Earth; currently cannot leave his dimensional prison under his own power or another''s help.; Minions: a bodyguard of six Baal-rogs; can summon 1D6 more once an hour, up to 60', '[{"name":"All rogue skills","pct":98},{"name":"All technical skills","pct":80},{"name":"All espionage skills","pct":80},{"name":"Computer hacking","pct":74}]', 'Hand to Hand: Assassin; magically knows all languages; W.P. Blunt; W.P. Sword; W.P. Energy Rifle; W.P. Energy Heavy Weapons; Robot Combat: Basic.', 'Nightvision 600 ft, sees/turns invisible, regenerates 1D6x100 M.D./min, immune to disease, shapeshifts into any animal or humanoid; dimensional teleport unusable until he escapes his prison.', 'All necromantic spells and abilities; All spells levels 1-15 (spell strength 16)', 'All sensitive and super powers (equal to a 10th level psychic)', NULL, NULL, 'Sword of Hatred (Greater rune weapon, 3D6x10 M.D., doubled vs creatures of magic; animated, can fight itself up to 200 ft away); Ahriman Mark I Demonic Robot Vehicle (Rune Assault Suit; Main Body 1,800 M.D.C., regenerates 2D4x10 M.D.C./5 min; forearm cannons and spikes; can separate into six living-demon components)', NULL, 'A calculating tyrant who savors corrupting the strongest defenders of good and delights in their suffering.', 'Demon Lords and gods of darkness from all pantheons', 'All the forces of good', 'Evil twin of Ahura Mazda, also known as Angra Mainyu; imprisoned in his own dimension, he plots to free ancient evils and conquer the Megaverse.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.194-195');
  'aeshma', 'Aeshma', 'Aeshma Fuhriman', 'Fury', 'rifts', 'Deity', '14th level warrior and 8th level ley line walker', 14, 'Diabolic', NULL, '6 to 26 feet tall (1.8 to 7.9 m)', 'Varies with size', '{"IQ":16,"ME":18,"MA":19,"PS":52,"PP":22,"PE":21,"PB":14,"Spd":77}', 700, 2000, 27000, 2000, NULL, NULL, 16, '{"attacks":7,"initiative":4,"strike":10,"parry":7,"dodge":7,"roll":3,"pull":3}', '+3 to pull punch, +3 to roll w/ impact or fall; M.D.C. reduced to 5,400 on Rifts Earth; retreats near his last 100 M.D.C. and seeks revenge later.', '[{"name":"All espionage skills","pct":98},{"name":"All rogue skills","pct":98}]', 'Hand to Hand: Assassin; magically knows all languages.', 'Nightvision 200 ft, sees/turns invisible, leaps 50 ft high or 100 ft long, regenerates 2D6x10 M.D./min, immune to heat and fire, teleports, and metamorphs into a bulky human, rhinoceros, bull/buffalo, or lion.', 'All spells levels 1-3; Carpet of adhesion; Magic net; Blind; Shadow meld; Fool''s gold; Domination; Apparition; Agony; Call lightning; Fire ball; Hallucination', NULL, NULL, NULL, 'Dragon Thunderer Axe (2D4x10 M.D. plus a thunderclap on strike; casts invulnerability/levitation/summon rain/calm storms)', NULL, 'A sadistic, impulsive brute who tortures for amusement and retreats only when overwhelmed, always seeking revenge.', 'Forces of darkness, particularly demon lords; Raksasha demon lords', 'Champions of Light, human or supernatural', 'Persian god of fury and discord; a shock trooper for Ahriman who incites riots and hunts the children of Ahura Mazda.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.197');
  'ahzi-dahaka', 'Ahzi Dahaka', NULL, 'The Great Deceiver', 'rifts', 'Greater Devil', '12th level ley line walker and mind melter', 12, 'Diabolic', NULL, '6 to 36 feet tall (1.8 to 11 m)', 'Varies with size', '{"IQ":26,"ME":23,"MA":25,"PS":36,"PP":20,"PE":23,"PB":5,"Spd":38}', 1600, 3000, 46000, 3000, 1200, NULL, 17, '{"attacks":6,"initiative":3,"strike":7,"parry":6,"dodge":6,"roll":3,"damage":21}', '+21 to S.D.C. damage, +3 to roll w/ impact or fall; M.D.C. reduced to 9,200 on Rifts Earth; Horror Factor 17 applies only when his true shape is revealed.', '[{"name":"All espionage skills","pct":80},{"name":"Prowl","pct":80},{"name":"Palming","pct":80},{"name":"Pickpocket","pct":80},{"name":"Computer hacking","pct":80},{"name":"Computer programming","pct":80},{"name":"Lore: demons and monsters","pct":80},{"name":"Cryptography","pct":80}]', 'Hand to Hand: Assassin; W.P. Sword; W.P. Energy Rifle.', 'Nightvision 1200 ft, hawk-like vision (2 miles), sees/turns invisible, shapeshifts into any humanoid, regenerates 2D4x10 M.D./min, immune to poison/disease, resists fire/heat/cold, and can send up to 6 fragments of himself to possess humanoids on other worlds.', 'All spell magic levels 1-6; Agony; Constrain being; Curse: phobia; Mute; Mystic portal; Metamorphosis: mist', 'All sensitive powers; Bio-manipulation; Mind block; Mind block auto-defense; Psi-sword', NULL, NULL, NULL, NULL, 'A hypocritical master manipulator who mirrors whatever emotion suits the moment to earn trust and turn people against each other.', 'Forces of darkness, particularly demon lords', 'Champions of Light, human or supernatural', 'Ahriman''s second-in-command, a former minor devil elevated to great power; possesses mortals to found cults across the Megaverse.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.197-198');
  'jahi', 'Jahi', NULL, 'Goddess of Lust', 'rifts', 'Unique Demon Assassin', '10th level assassin, 5th level sorceress', 10, 'Diabolic', NULL, '6 to 20 feet tall (1.8 to 6.1 m)', 'Varies with size', '{"IQ":18,"ME":17,"MA":22,"PS":30,"PP":19,"PE":18,"PB":25,"Spd":33}', 95, 250, 1250, 560, NULL, NULL, 15, '{"attacks":6,"initiative":5,"strike":6,"parry":2,"dodge":2,"roll":3,"damage":15}', '+15 to S.D.C. damage, +3 to roll w/ impact or fall; Horror Factor 15 applies only after her true nature is revealed. Special: Aura of Enticement (target saves vs psionics 16 or becomes irresistibly attracted, reduced to one action/attack and oblivious to danger; used only when ordinary seduction fails).', '[{"name":"All espionage skills","pct":78},{"name":"All domestic skills","pct":78},{"name":"Palming","pct":78},{"name":"Streetwise","pct":78}]', 'Hand to Hand: Assassin; W.P. Knife; W.P. Blunt; W.P. Energy Rifle.', 'Nightvision 600 ft, sees/turns invisible, shapeshifts into any female form, regenerates 1D6x10 M.D./min, dimensional teleport at 62%.', 'Blinding flash; See aura; Befuddle; Chameleon; Concealment; Detect concealment; Fear; Heavy breathing; Armor of Ithan; Fool''s gold; Shadow meld; Domination; Horrific illusion; Sleep; Fire ball; Impervious to energy; Mask of deceit; Words of truth; Agony; Life drain; Hallucination; Protection circle: simple', NULL, NULL, NULL, NULL, NULL, 'Sweet and submissive-seeming while on a mission, but brutal and sadistic when free to be herself; delights in betraying overconfident men.', 'Ahriman (lover and favorite ally)', NULL, 'Demonness and Ahriman''s lover; seduces and assassinates targets, using an irresistible Aura of Enticement as a last resort.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.198-199');
  'nasu', 'Nasu', 'Nasu Pestihl', 'the Corpse', 'rifts', 'Deity', '14th level necromancer', 14, 'Miscreant', NULL, '8 to 26 feet tall (2.4 to 7.9 m)', 'Varies with size', '{"IQ":20,"ME":20,"MA":22,"PS":30,"PP":17,"PE":30,"PB":5,"Spd":88}', 800, 2000, 28000, 4000, NULL, NULL, 19, '{"attacks":5,"initiative":1,"strike":3,"parry":5,"dodge":5,"roll":2,"damage":15}', '+15 to S.D.C. damage, +2 to roll w/ impact or fall; M.D.C. reduced to 5,600 on Rifts Earth. Vulnerable: fire and holy weapons do triple damage, weapons of Millennium Tree wood do 10x damage. Special powers: Winds of Pestilence (disease-gust every other melee round, 10 ft radius, save vs poison 16 or fall ill per a d100 disease table) and Touch of Pestilence (inflicts any of those diseases by touch once per melee; armor/vehicles block it).', '[{"name":"All medical skills","pct":98},{"name":"All lore","pct":98},{"name":"Language","pct":98}]', 'Hand to Hand: Expert.', 'Nightvision 200 ft, sees/turns invisible, regenerates 3D6x10 M.D./min, resists cold, immune to disease, teleports, and can animate/control 1D6x100 dead.', 'All necromantic abilities and spells; Spell magic levels 1-4; Horrific illusion; Fire ball; Constrain being; Life drain; Minor curse; Sickness; Spoil; Circle of protection: simple; Banishment; Sanctum; Transformation', NULL, NULL, NULL, NULL, NULL, 'Sinister and morbid; treats killing as an unpleasant duty he performs for the victim''s supposed own good.', 'Forces of darkness, particularly vampires and necromancers', 'Champions of Light, human or supernatural', 'God of decay and disease, loyal to Ahriman; a necromancer who spreads a variety of magical plagues and commands legions of undead.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.199-201');
  'ishtar', 'Ishtar', NULL, 'Goddess of Love & War', 'rifts', 'Deity', '15th level ley line walker and warrior', 15, 'Anarchist', NULL, 'Ranges from 6 to 24 feet (1.8 m to 7.3 m)', 'Varies with size', '{"IQ":22,"ME":21,"MA":26,"PS":40,"PP":24,"PE":23,"PB":27,"Spd":88}', 1300, 3000, 43000, 3000, 400, NULL, 14, '{"attacks":8,"initiative":4,"strike":11,"parry":8,"dodge":8,"roll":3,"pull":3}', '8,600 M.D.C. on Rifts Earth (alt to 43,000); +25 to S.D.C. damage; +5 to save vs magic; +4 to save vs psionics; +11 to save vs horror factor; two attacks per melee if using magic instead of eight hand to hand/psionic.', NULL, 'All domestic, espionage and rogue skills, plus horsemanship, sail boat, and land navigation, at 98%; magically knows all languages; W.P. Sword, W.P. Spear, W.P. Energy Pistol, W.P. Energy Rifle; Hand to Hand: Assassin.', 'Nightvision 200 ft, sees invisible, bio-regenerates 3D6x10 M.D.C./min, resists fire and cold (half damage), healing touch restores 1D6x10, teleports self 81%, dimensional teleport 78%.', 'all spells levels 1-4; calling; apparition; fire ball; impervious to energy; mask of deceit; escape; sleep; globe of silence; magic pigeon; tongues; eyes of the wolf; invulnerability; negate magic; protection circle: simple', 'empathy; alter aura; clairvoyance; levitation; psychic surgery; bio-manipulation; group mind block; mind block auto-defense', NULL, NULL, 'Sword of Victory (greatest rune weapon, I.Q. 12, telepathic link; 2D6x10 M.D., double vs dragons, vampires, demons and Splugorth); Spear of Vengeance (2D4x10 M.D., thrown, returns, 2000 ft range); Magical Scale Armor (1,000 M.D.C., weightless)', NULL, 'Fickle and spoiled; alternates between charming devotion and cruel vindictiveness; bored quickly with lovers, vengeful when spurned.', 'many gods and mortals across several pantheons and humanoid races (unnamed)', 'Ereshkigal; many unnamed rivals (roughly twice her allies, per the book)', 'Sumerian goddess of love and war, daughter of Anu; fickle and passionate, rival of underworld goddess Ereshkigal; also known as Innana.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.44-46');
  'garuda', 'Garuda', NULL, 'The Bird God', 'rifts', 'Deity', '15th level ley line walker', 15, 'Principled', NULL, 'Varies: can shrink to a normal bird or grow into a giant winged humanoid 30 feet (9 m) tall', 'Varies with size', '{"IQ":22,"ME":22,"MA":24,"PS":50,"PP":21,"PE":24,"PB":19,"Spd":38}', 1500, 2500, 40000, 3000, 500, NULL, 15, '{"attacks":6,"initiative":3,"strike":6,"parry":8,"dodge":8,"roll":2,"pull":4}', '8,000 M.D.C. on Rifts Earth (alt to 40,000); flying Spd 220 (150 mph/241 km) vs 38 on the ground; +35 to S.D.C. damage; +6 to save vs magic; +5 to save vs psionics; +8 to save vs horror factor; can alter size at will; two attacks per melee if using magic instead of six hand to hand/psionic.', NULL, 'All wilderness, technical and domestic skills at 98%; magically knows all languages; Hand to Hand: Expert.', 'Alters size at will, nightvision 1200 ft, keen hawk-like vision, sees invisible, bio-regenerates 2D6x10 M.D.C./min, turns 2D4x10 dead, teleports self and dimensionally at 67%, healing touch restores 4D6.', 'all spells levels 1-4; carpet of adhesion; blind; repel animals; calling; domination; mask of deceit; metamorphosis: human; negate magic; speed of the snail; anti-magic cloud; remove curse; summon and control animals; dimensional portal', 'all sensitive powers; all healing powers', NULL, NULL, NULL, NULL, 'Dignified, loyal, and principled; welcomes those who stand up for their beliefs; scorns bigots and human supremacists.', 'Vishnu; Brahma; Ra; the bird-gods of the Egyptian Pantheon; the other animal deities; the pantheons of light (general)', 'Indra (rival); dragons and serpents (sworn enemies); demons and evil gods he pursues as Vishnu''s ally', 'Hindu bird-god with an eagle''s head, wings, and taloned feet on a human torso; ally and mount of Vishnu; hunts dragons, serpents, and criminals; rival of Indra.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.130-131');















-- Rewording rows the Dragons and Gods script (#1166) inserted: each of these
-- shared an eight-word run with the book. Same meaning, own words.
UPDATE notable_npcs SET description = 'Demigod punished by the Gods of Light with a permanent dog form; heads a small, fanatical cult of assassins.' WHERE slug = 'chantico';
UPDATE notable_npcs SET description = 'Queen of the Gargoyles: sly, faithless, and dangerous to cross - her rivals tend to vanish or die unexpectedly.' WHERE slug = 'lady-leeves';
UPDATE notable_npcs SET disposition = 'Scheming and disloyal; hungry for power over Hades and the Palladium world alike.' WHERE slug = 'lady-leeves';

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'chantico description reworded' AS assertion, count(*) AS got, 1 AS want
  FROM notable_npcs WHERE slug = 'chantico' AND description = 'Demigod punished by the Gods of Light with a permanent dog form; heads a small, fanatical cult of assassins.';
SELECT 'lady-leeves description reworded' AS assertion, count(*) AS got, 1 AS want
  FROM notable_npcs WHERE slug = 'lady-leeves' AND description = 'Queen of the Gargoyles: sly, faithless, and dangerous to cross - her rivals tend to vanish or die unexpectedly.';
SELECT 'lady-leeves disposition reworded' AS assertion, count(*) AS got, 1 AS want
  FROM notable_npcs WHERE slug = 'lady-leeves' AND disposition = 'Scheming and disloyal; hungry for power over Hades and the Palladium world alike.';
